    INSERT INTO public.kb_source_candidates (id, batch_id, candidate_key, candidate_status, proposed_source_type, title, publisher, publication_date, source_url, external_identifier, rights_status, source_locator, original_excerpt, confidence, ambiguity_notes, proposed_data, data_classification)
    VALUES
      ('78680f09-1c1d-594f-9256-66ff5beb6512', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-binder-high-dose', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Generische ''Heilkrise'', Einlaeufe und sehr hohe Binderdosen', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-binder-high-dose', 'unknown', 'Folge 005 07:32-08:46; 15:47-20:08 E005-005', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-binder-high-dose","aliases":["Generische ''Heilkrise'', Einlaeufe und sehr hohe Binderdosen"],"tags":["Ausleitung","Erfahrungsheilkunde","Folge 005","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt","Sprecheraussage"],"therapeutic_topics":["Ausleitung"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Nicht durch Dosiserhoehung auf ungeklaerte Verschlechterung reagieren. Kaffee-/Darmeinlaeufe koennen Kolitis, Perforation, Infektion, Dehydratation und Elektrolytstoerung verursachen. Aktivkohle/Zeolith binden Arzneien; Algenprodukte koennen Allergie, Photosensibilisierung, Magen-Darm-Beschwerden und Kontamination verursachen.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E005-005; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nErstverschlimmerung nach Ausleitung wird mit Alkohol- oder Nikotinentzug verglichen. Empfohlen werden je nach Ausloeser ein flacher Teeloeffel Zeolith drei- bis viermal taeglich oder 40-50 Chlorella-Tabletten zwei- bis dreimal taeglich, ausserdem Einlaeufe/Kolonhydrotherapie, Kaffeeeinlaeufe, Leberwickel, Sauna, Nux vomica und lebenslange Chlorella-Einnahme.\n\n## Genannte Mittel oder Verfahren\n- Zeolith, Chlorella, Einlaeufe, Kolonhydrotherapie, Kaffeeeinlaeufe, Sauna, Leberwickel, Mariendistel, Bitterkraeuter und homoeopathisches Nux vomica.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nZeolith: 1 flacher Teeloeffel 3-4x/Tag. Chlorella: 40-50 Tabletten 2-3x/Tag. Behauptung lebenslanger Sicherheit; anekdotisch sogar 1 Pfund pro Tag.\n\n## Sprecher und Fundstellen\n- Folge 005 · 07:32-08:46; 15:47-20:08 · E005-005 · Dr. Dietrich Klinghardt\n\n## Unabhängige Evidenzeinordnung\nEine allgemeine Detox-''Heilkrise'' ist kein anerkannter Mechanismus. Beschwerden koennen Nebenwirkungen, Wechselwirkungen oder Krankheitsprogression bedeuten. Fuer die extremen Chlorella-Anekdoten, Kaffeeeinlaeufe, Leberwickel, Kolonreinigung oder Nux vomica nach Narkose fehlt Wirksamkeitsevidenz. Sauna-Schweissmessungen beweisen keine klinisch relevante Koerperlastsenkung.\n\n## Sicherheit · BEACHTEN\nNicht durch Dosiserhoehung auf ungeklaerte Verschlechterung reagieren. Kaffee-/Darmeinlaeufe koennen Kolitis, Perforation, Infektion, Dehydratation und Elektrolytstoerung verursachen. Aktivkohle/Zeolith binden Arzneien; Algenprodukte koennen Allergie, Photosensibilisierung, Magen-Darm-Beschwerden und Kontamination verursachen.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('5cd50016-a40b-5fa9-9b77-0fde53554ce4', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-activated-charcoal', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Aktivkohle', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-activated-charcoal', 'unknown', 'Folge 010 1:27:33-1:28:22 E010-009', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-activated-charcoal","aliases":["Aktivkohle"],"tags":["Ausleitung","Erfahrungsheilkunde","Folge 010","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt","Sprecheraussage"],"therapeutic_topics":["Ausleitung"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Arzneibindung, Aspiration, Obstipation und Obstruktion möglich.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E010-009; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nWirksamer Binder\n\n## Genannte Mittel oder Verfahren\n- Aktivkohle\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nLaut Klinghardt nicht länger als 3-4 Tage\n\n## Sprecher und Fundstellen\n- Folge 010 · 1:27:33-1:28:22 · E010-009 · Dr. Dietrich Klinghardt\n\n## Unabhängige Evidenzeinordnung\nNur für ausgewählte akute orale Vergiftungen unter toxikologischer Anleitung; keine allgemeine Nanopartikelentgiftung.\n\n## Sicherheit · BEACHTEN\nArzneibindung, Aspiration, Obstipation und Obstruktion möglich.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('80b2adf8-7e37-5be9-99a7-82374ce37539', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-aluminium-detox-binders', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Alu-Tops, Koriander, Chlorella und Zeolith mit hohen Langzeitdosen', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-aluminium-detox-binders', 'unknown', 'Folge 014 34:55-37:23 E014-013', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-aluminium-detox-binders","aliases":["Alu-Tops, Koriander, Chlorella und Zeolith mit hohen Langzeitdosen"],"tags":["Ausleitung","Erfahrungsheilkunde","Folge 014","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Ausleitung"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Die hohen, monatelangen Dosen nicht ohne Produktprüfung, Medikationsabgleich sowie Nieren-/Leber- und Ernährungsbeurteilung übernehmen. Binder können Arzneien/Nährstoffe binden; Zeolithqualität und Verunreinigungen sind produktabhängig. Bei Kindern besonders keine Selbstbehandlung.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E014-013; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt nennt Koriander als stärksten gemeinsamen Ausleitungsstoff. Ein in seiner Praxis entwickeltes, als ''Alutops/Alu-Tops'' erfasstes Gemisch enthalte vier Pflanzen; im Track sind wahrscheinlich Inula, Koriander, ein unverständliches ''Badana'' und Horsetail/Schachtelhalm zu hören. Hauptbestandteile der Ausleitung seien Alu-Tops und Koriander. Dazu gebe er Bindemittel und wechsle meist tageweise Chlorella und Zeolith. Statt einer Folienangabe von acht Tabletten dreimal täglich verwende er als Grundtherapie 15 Chlorella-Tabletten à 250 mg zweimal täglich, bei guter Verträglichkeit dreimal täglich, während einer intensiven Phase von sechs bis zwölf Monaten. Zeolith sei als flacher Teelöffel zweimal täglich ''nicht zu viel''; schriftlich empfehle man widersprüchlich einen Viertel Teelöffel zweimal oder viermal täglich.\n\n## Genannte Mittel oder Verfahren\n- Koriander; Alu-Tops; Chlorella; Zeolith; täglicher Wechsel der Binder\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nChlorella: 15 × 250 mg = 3,75 g pro Einnahme, 2×/Tag = 7,5 g/Tag; bei Verträglichkeit 3×/Tag = 11,25 g/Tag; intensiv 6-12 Monate. Folie: 8 Tabletten 3×/Tag. Zeolith: flacher TL 2×/Tag; schriftlich 1⁄4 TL 2× oder 4×/Tag, im Track widersprüchlich.\n\n## Sprecher und Fundstellen\n- Folge 014 · 34:55-37:23 · E014-013 · DK\n\n## Unabhängige Evidenzeinordnung\nKein belastbarer Humanbeleg wurde identifiziert, dass diese Kombination Gehirn- oder Epiphysenaluminium entfernt oder Autismus/Demenz behandelt. Gereinigter Klinoptilolith reduzierte in einer kleinen randomisierten Studie die gleichzeitige enterale Aufnahme eines Bleitracers [S25]; das ist kein Nachweis für systemische Aluminium- oder Gehirnausleitung. Nahrungsergänzungen werden nicht wie Arzneimittel vorab auf Wirksamkeit zugelassen [S36].\n\n## Sicherheit · HOCH\nDie hohen, monatelangen Dosen nicht ohne Produktprüfung, Medikationsabgleich sowie Nieren-/Leber- und Ernährungsbeurteilung übernehmen. Binder können Arzneien/Nährstoffe binden; Zeolithqualität und Verunreinigungen sind produktabhängig. Bei Kindern besonders keine Selbstbehandlung.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('3eb35e4d-e6cd-5303-818e-40b778e35d69', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-zoster-neuralgia', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Herpes zoster und Neuralgie', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-zoster-neuralgia', 'unknown', 'Folge 005 20:09-23:07 E005-007', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-zoster-neuralgia","aliases":["Herpes zoster und Neuralgie"],"tags":["Erfahrungsheilkunde","Folge 005","Interne Prüfung","Klinghardt-Talks","Pathogene und Infektionen","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt","Sprecheraussage"],"therapeutic_topics":["Pathogene und Infektionen"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Akuter Zoster braucht rechtzeitige etablierte Abklaerung und je nach Situation antivirale Therapie. Phenytoin hat enge therapeutische Breite, starke Interaktionen sowie schwere Haut-, Leber-, Blut- und Herzrisiken. Bienengift kann anaphylaktisch wirken. Grossvolumige subkutane Injektionen koennen Infektion, Gewebeschaden und Volumenprobleme verursachen.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E005-007; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nWenn Zosterschmerz nicht binnen sechs Wochen kontrolliert sei, bleibe er oft lebenslang. Genannt werden Herpes-Zoster-Nosode plus Eigenblut, Phenytoin 200 mg zweimal taeglich fuer drei bis vier Tage, Capsaicin als angeblicher Schwarzpfefferextrakt, Bienengift/Procain-Quaddeln und 5%-Dextrose 70-150 ml subkutan.\n\n## Genannte Mittel oder Verfahren\n- Nosode, Eigenblut, Phenytoin/Dilantin, topisches Capsaicin, Bienengift plus Procain und subkutane 5%-Dextrose.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nPhenytoin 200 mg 2x/Tag fuer 3-4 Tage. Bienengift entsprechend 1-2 Stichen. Dextrose 5%: 70-150 ml subkutan in der Region.\n\n## Sprecher und Fundstellen\n- Folge 005 · 20:09-23:07 · E005-007 · Dr. Dietrich Klinghardt\n\n## Unabhängige Evidenzeinordnung\nKeine starre Sechs-Wochen-Grenze: Post-Zoster-Neuralgie kann Monate/Jahre anhalten, sich aber bessern. Nosode/Eigenblut und Bienengift sind nicht leitliniengestuetzt. Orales Phenytoin in diesem Kurzschema ist keine etablierte Zoster- oder Trigeminusbehandlung. Capsaicin stammt aus Capsicum/Chili, nicht schwarzem Pfeffer; ein professionelles 8%-Pflaster kann bei peripherem neuropathischem Schmerz helfen. Dextrose-Injektionen bleiben experimentell.\n\n## Sicherheit · HOCH\nAkuter Zoster braucht rechtzeitige etablierte Abklaerung und je nach Situation antivirale Therapie. Phenytoin hat enge therapeutische Breite, starke Interaktionen sowie schwere Haut-, Leber-, Blut- und Herzrisiken. Bienengift kann anaphylaktisch wirken. Grossvolumige subkutane Injektionen koennen Infektion, Gewebeschaden und Volumenprobleme verursachen.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('d76760c7-4d19-53dd-9df1-a2ecfec15b18', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-stroke-vitamin-c-dmso', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Schlaganfallursachen und DMSO-/Vitamin-C-Infusionsrezept', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-stroke-vitamin-c-dmso', 'unknown', 'Folge 022 1:00:13-1:03:29 E022-028', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-stroke-vitamin-c-dmso","aliases":["Schlaganfallursachen und DMSO-/Vitamin-C-Infusionsrezept"],"tags":["Erfahrungsheilkunde","Erkrankungen und Symptome","Folge 022","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Erkrankungen und Symptome"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Bei Schlaganfallzeichen sofort Notruf, keine Praxisinfusion abwarten. Unklare DMSO-/Vitamin-C-Mischungen bergen Reinheits-, Osmolaritäts-, Nieren-, Hämolyse-, Interaktions- und Verzögerungsrisiken.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E022-028; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nBei Halbseitenlähmung fragt Klinghardt zunächst nach Diabetes, Hypertonie, Impfung, unerwartetem Ereignis oder emotionalem Auslöser. Sein ''goldenes'' Post-Stroke-Verfahren sei eine Infusion mit 25 g Vitamin C in 500 ml Flüssigkeit plus einer aus rechtlichen Gründen nicht genannten DMSO-Dosis. Dann berichtet er, jenseits der Grenze in Mexiko oder Kanada würden 25 ml Vitamin C und 25 ml DMSO über eine bis anderthalb Stunden gemischt; die Einheiten widersprechen sich und bleiben unklar. DMSO öffne die Mikrozirkulation der Penumbra und bringe noch lebende, aber hungernde Nervenzellen vollständig zurück.\n\n## Genannte Mittel oder Verfahren\n- Intravenöses Vitamin C plus DMSO nach Schlaganfall\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\n25 g Vitamin C in 500 ml; DMSO-Dosis zurückgehalten. Hörensagen: je 25 ml Vitamin C und DMSO über 1-1,5 Stunden.\n\n## Sprecher und Fundstellen\n- Folge 022 · 1:00:13-1:03:29 · E022-028 · DK\n\n## Unabhängige Evidenzeinordnung\nDie ischämische Penumbra ist real, aber Behandlung ist hochgradig zeitkritisch und hängt von Bildgebung, Thrombolyse/Thrombektomie und Schlaganfalltyp ab [S29]. DMSO ist nicht als IV-Schlaganfallmittel gekennzeichnet [S08]; der Track zeigt keine kontrollierte Studie für diese Mischung.\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Bei Schlaganfallzeichen sofort Notruf, keine Praxisinfusion abwarten. Unklare DMSO-/Vitamin-C-Mischungen bergen Reinheits-, Osmolaritäts-, Nieren-, Hämolyse-, Interaktions- und Verzögerungsrisiken.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('abf57d97-4d53-5d4e-850e-89a9b2f48334', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-dapson-lyme', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Dapson-Kombination bei Lyme/PTLDS', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-dapson-lyme', 'unknown', 'Folge 003 08:35-24:34 E003-001', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-dapson-lyme","aliases":["Dapson-Kombination bei Lyme/PTLDS"],"tags":["Erfahrungsheilkunde","Folge 003","Interne Prüfung","Klinghardt-Talks","Pathogene und Infektionen","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Dr. Richard Horowitz (Einzelzuordnung nicht strukturell kodiert)","Sprecheraussage"],"therapeutic_topics":["Pathogene und Infektionen"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Hochrisiko-Off-label-Anwendung, keine Selbstbehandlung. Dapson kann auch bei normaler G6PD-Aktivitaet Haemolyse, Anemie und Methaemoglobinaemie ausloesen; selten Agranulozytose, aplastische Anemie, DRESS, SJS/TEN, Hepatitis und Neuropathie. Engmaschiges fachmedizinisches Monitoring ist unverzichtbar.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E003-001; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nHorowitz beschreibt Dapson als oral wirksames, liquorgaengiges, antiinflammatorisches und gegen sogenannte Biofilm-Persister gerichtetes Mittel. Er berichtet hohe Verbesserungs- und Remissionsraten aus seiner Praxis.\n\n## Genannte Mittel oder Verfahren\n- Dapson plus Rifampicin und Doxycyclin oder Minocyclin; im zweiten Monat Azithromycin. Spaetere Hochdosis-Pulse enthalten laut Publikationen weitere Arznei- und Supplementkomponenten.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nIm Video: vier Wochen 100 mg Dapson zweimal taeglich. Abschluss mit 400 mg pro Tag fuer vier Tage; bei behaupteter Bartonella-Koinfektion sechs Tage. Gesamtdauer des Hauptprotokolls etwa acht bis neun Wochen.\n\n## Sprecher und Fundstellen\n- Folge 003 · 08:35-24:34 · E003-001 · Dr. Dietrich Klinghardt; Dr. Richard Horowitz (Einzelzuordnung nicht strukturell kodiert)\n\n## Unabhängige Evidenzeinordnung\nSehr niedrige klinische Evidenz: retrospektive, unkontrollierte Praxisserien mit Selbstberichten, Polypharmazie, Selektion und teils ueberlappenden Patienten. Keine randomisierte, verblindete oder kontrollierte Humanstudie. IDSA/AAN/ACR, AWMF und NICE empfehlen Dapson bei Lyme/PTLDS nicht.\n\n## Sicherheit · BEACHTEN\nHochrisiko-Off-label-Anwendung, keine Selbstbehandlung. Dapson kann auch bei normaler G6PD-Aktivitaet Haemolyse, Anemie und Methaemoglobinaemie ausloesen; selten Agranulozytose, aplastische Anemie, DRESS, SJS/TEN, Hepatitis und Neuropathie. Engmaschiges fachmedizinisches Monitoring ist unverzichtbar.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('23fcd018-d42b-564c-8814-43e6f7bd6eb9', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-dapson-children-autism', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Kinder und Autismus', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-dapson-children-autism', 'unknown', 'Folge 003 24:34-36:36 E003-004', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-dapson-children-autism","aliases":["Kinder und Autismus"],"tags":["Erfahrungsheilkunde","Erkrankungen und Symptome","Folge 003","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Dr. Richard Horowitz (Einzelzuordnung nicht strukturell kodiert)","Sprecheraussage"],"therapeutic_topics":["Erkrankungen und Symptome"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Besonders hoher Warnstatus. Paediatrische Off-label-Polypharmazie darf nicht aus diesem Video abgeleitet werden. Ein publizierter jugendlicher Fall zeigte Hb bis 9,3 g/dl und erniedrigtes Haptoglobin. Rifampicin-Fachinformationen raten von intermittierender Therapie ab und warnen dabei unter anderem vor Thrombozytopenie, haemolytischer Anemie, Nierenversagen, Schock und Anaphylaxie. Kinder benoetigen spezialisierte paediatrische Diagnostik und etablierte Versorgung.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E003-004; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nHorowitz berichtet einzelne kindliche Fallbeobachtungen und vermutet Infektionen, Toxine und Neuroentzuendung als zentrale Autismustreiber. Er sagt selbst, nicht genuegend Kindererfahrung und keine ausreichenden Daten zu haben, schlaegt dennoch ein niedrig dosiertes Dapson-/Rifampicin-Vorgehen vor.\n\n## Genannte Mittel oder Verfahren\n- Dapson, gelegentlich gepulstes Rifampicin, Folsauere, Glutathion und hochdosierter Brokkolisamenextrakt/Sulforaphan.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nVorschlag im Video: Dapson 25 mg jeden zweiten Tag fuer eine Woche, danach 25 mg taeglich; 50 mg seien oft ausreichend, meist nicht ueber 100 mg. Die anschliessende Rifampicin-Passage ist sprachlich unvollstaendig und nicht verlaesslich als Dosis transkribierbar; erwaehnt wird ein intermittierender Wochenpuls. Keine validierte gewichtsspezifische Berechnung.\n\n## Sprecher und Fundstellen\n- Folge 003 · 24:34-36:36 · E003-004 · Dr. Dietrich Klinghardt; Dr. Richard Horowitz (Einzelzuordnung nicht strukturell kodiert)\n\n## Unabhängige Evidenzeinordnung\nKeine kontrollierte Dapson-Studie bei Kindern mit Lyme oder Autismus. Zwei serologische Untersuchungen fanden keine erhoehte Lyme-Seropositivitaet bei Kindern mit Autismus. Sulforaphan zeigt nur vorlaeufige Signale aus kleinen heterogenen Studien.\n\n## Sicherheit · HOCH\nBesonders hoher Warnstatus. Paediatrische Off-label-Polypharmazie darf nicht aus diesem Video abgeleitet werden. Ein publizierter jugendlicher Fall zeigte Hb bis 9,3 g/dl und erniedrigtes Haptoglobin. Rifampicin-Fachinformationen raten von intermittierender Therapie ab und warnen dabei unter anderem vor Thrombozytopenie, haemolytischer Anemie, Nierenversagen, Schock und Anaphylaxie. Kinder benoetigen spezialisierte paediatrische Diagnostik und etablierte Versorgung.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('d62b115a-2d19-5e1b-a542-8fc85b7c370f', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-glutathione-covid', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: COVID, Long COVID und Virusreaktivierung', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-glutathione-covid', 'unknown', 'Folge 003 36:36-42:55 E003-007', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-glutathione-covid","aliases":["COVID, Long COVID und Virusreaktivierung"],"tags":["Erfahrungsheilkunde","Folge 003","Interne Prüfung","Klinghardt-Talks","Pathogene und Infektionen","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Dr. Richard Horowitz (Einzelzuordnung nicht strukturell kodiert)","Sprecheraussage"],"therapeutic_topics":["Pathogene und Infektionen"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Nicht zur COVID-Selbstbehandlung. Akute Atemnot ist ein Notfall-/Abklaerungssymptom. Spironolacton, Dipyridamol und Famciclovir haben eigene Kontraindikationen und Interaktionen; Kombinationen benoetigen klare Indikation.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E003-007; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nGlutathion habe in Fallberichten Atemnot rasch gebessert; eine kleine etwa 40-Personen-Studie zu Dapson habe ARDS verhindert. Long COVID wird unter anderem mit Epstein-Barr-/HHV-6- und Bartonella-Reaktivierung verbunden.\n\n## Genannte Mittel oder Verfahren\n- Glutathion, Dapson, Famciclovir, Spironolacton und Dipyridamol/Persantine; keine vollstaendige Kombination oder Dosis.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nGlutathion-Injektion 2.000 mg als berichtetes Praxisbeispiel. Andere Dosen fehlen.\n\n## Sprecher und Fundstellen\n- Folge 003 · 36:36-42:55 · E003-007 · Dr. Dietrich Klinghardt; Dr. Richard Horowitz (Einzelzuordnung nicht strukturell kodiert)\n\n## Unabhängige Evidenzeinordnung\nDapson bei COVID/ARDS ist unbelegt; keine Leitlinienempfehlung. EBV-Reaktivierung kann in Teilpopulationen untersucht werden, beweist aber nicht die breite Kausalitaet. Bartonella als Long-COVID-Ursache ist unbelegt.\n\n## Sicherheit · BEACHTEN\nNicht zur COVID-Selbstbehandlung. Akute Atemnot ist ein Notfall-/Abklaerungssymptom. Spironolacton, Dipyridamol und Famciclovir haben eigene Kontraindikationen und Interaktionen; Kombinationen benoetigen klare Indikation.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('b7bbb348-2cc0-55eb-8f25-bf2085ba7b48', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-disulfiram-low-dose', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Disulfiram 67,5 mg taeglich', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-disulfiram-low-dose', 'unknown', 'Folge 004 56:35-57:37 E004-015', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-disulfiram-low-dose","aliases":["Disulfiram 67,5 mg taeglich"],"tags":["Erfahrungsheilkunde","Folge 004","Interne Prüfung","Klinghardt-Talks","Pathogene und Infektionen","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Dr. Neil Nathan (Einzelzuordnung nicht strukturell kodiert)","Sprecheraussage"],"therapeutic_topics":["Pathogene und Infektionen"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Auch niedrige Dosen koennen Hepatitis, Neuropathie, Psychose und Interaktionen verursachen. Alkoholreaktionen sind schwer und bis 14 Tage nach Absetzen moeglich; versteckte Alkoholquellen beachten. Metronidazol ist kontraindiziert. Keine Selbstbehandlung.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E004-015; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nNach Problemen mit hoeheren Dosen setzt Nathan Disulfiram als Zusatz mit 67,5 mg einmal taeglich ein und vermutet Nutzen gegen Borrelia und Bartonella; wegen vieler gleichzeitiger Therapien sei der Einzeleffekt schwer trennbar.\n\n## Genannte Mittel oder Verfahren\n- Disulfiram.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\n67,5 mg einmal taeglich, im Video exakt genannt.\n\n## Sprecher und Fundstellen\n- Folge 004 · 56:35-57:37 · E004-015 · Dr. Dietrich Klinghardt; Dr. Neil Nathan (Einzelzuordnung nicht strukturell kodiert)\n\n## Unabhängige Evidenzeinordnung\nSehr niedrig. Die kleine 2025 publizierte Pilotstudie untersuchte andere, individualisierte Dosen, nur neun ausgewertete Personen und keinen reinen Placebo-Wirksamkeitsvergleich; mehrere Abbrueche, Leberwerterhoehungen und eine wahrscheinlich therapiebedingte Hospitalisierung. Kein Beleg fuer 67,5 mg oder Bartonella.\n\n## Sicherheit · BEACHTEN\nAuch niedrige Dosen koennen Hepatitis, Neuropathie, Psychose und Interaktionen verursachen. Alkoholreaktionen sind schwer und bis 14 Tage nach Absetzen moeglich; versteckte Alkoholquellen beachten. Metronidazol ist kontraindiziert. Keine Selbstbehandlung.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('bb977a5f-aef7-5250-9a6d-7f036fed0077', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-carpal-tunnel-thyroid', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Karpaltunnelsyndrom, Vitamin B6 und Schilddruesenhormon', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-carpal-tunnel-thyroid', 'unknown', 'Folge 005 45:26-46:10 E005-014', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-carpal-tunnel-thyroid","aliases":["Karpaltunnelsyndrom, Vitamin B6 und Schilddruesenhormon"],"tags":["Erfahrungsheilkunde","Erkrankungen und Symptome","Folge 005","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt","Sprecheraussage"],"therapeutic_topics":["Erkrankungen und Symptome"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Keine Schilddruesenhormone ohne TSH/fT4-Diagnostik; Ueberdosierung kann Vorhofflimmern, Osteoporose, Gewichtsverlust und kardiale Ereignisse ausloesen. B6-Gesamtdosis und Neuropathierisiko beachten. Fortschreitende Schwaeche/Thenaratrophie braucht zeitnahe neurologisch-handchirurgische Beurteilung.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E005-014; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKarpaltunnel soll mit relativ hoch dosiertem Vitamin B6 und natuerlichem Schilddruesenhormon, idealerweise 60 mg einmal taeglich fuer etwa sechs Wochen, meist deutlich besser werden. Alle frueher untersuchten Operationsbiopsien seien voller Borrelien; Karpaltunnel sei ein Lyme-Symptom.\n\n## Genannte Mittel oder Verfahren\n- Vitamin B6/Pyridoxin und natuerlicher Schilddruesenextrakt; Lyme-Zuordnung.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nSchilddruesenextrakt 60 mg 1x/Tag fuer etwa 6 Wochen. B6-Dosis nicht genannt.\n\n## Sprecher und Fundstellen\n- Folge 005 · 45:26-46:10 · E005-014 · Dr. Dietrich Klinghardt\n\n## Unabhängige Evidenzeinordnung\nCTS ist eine Medianuskompression; Hypothyreose kann Risikofaktor sein, ist aber nicht pauschale Ursache. Kontrollierte Studien fanden keinen klinisch relevanten B6-Nutzen. Zu viel B6 kann selbst Neuropathie erzeugen. Eine bestaetigte Hypothyreose wird individuell, meist mit Levothyroxin behandelt; natuerlicher Extrakt ist keine Routineempfehlung. Eine kleine alte Lyme-Studie beweist nicht, dass alle Biopsien Borrelien enthalten oder CTS generell Lyme ist.\n\n## Sicherheit · BEACHTEN\nKeine Schilddruesenhormone ohne TSH/fT4-Diagnostik; Ueberdosierung kann Vorhofflimmern, Osteoporose, Gewichtsverlust und kardiale Ereignisse ausloesen. B6-Gesamtdosis und Neuropathierisiko beachten. Fortschreitende Schwaeche/Thenaratrophie braucht zeitnahe neurologisch-handchirurgische Beurteilung.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('b942b162-e6a1-5703-a77e-ccd19bcccdf0', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-novalytic', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: NovalyticTM', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-novalytic', 'unknown', 'Folge 010 03:46-05:18; 58:09-1:30:01 E010-001', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-novalytic","aliases":["NovalyticTM"],"tags":["Erfahrungsheilkunde","Folge 010","Interne Prüfung","Klinghardt-Talks","Medikamente und Nährstoffe","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Maria Crisler","Sprecheraussage"],"therapeutic_topics":["Medikamente und Nährstoffe"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Etikettendosis nicht durch Videotitration überschreiten; Durchfall/Ausscheidungsbilder nicht automatisch als Entgiftung deuten.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E010-001; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nHydrogele/Polymere/angeblich weiche Robotik abbauen; Energie, Puffer, Organschutz, DNA-Partikel verlangsamen\n\n## Genannte Mittel oder Verfahren\n- NovalyticTM\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nIm Gespräch: mit 1 Kapsel nüchtern beginnen; auf 2, eventuell 3 Kapseln und bis zu 3 Einnahmen steigern.\n\n## Sprecher und Fundstellen\n- Folge 010 · 03:46-05:18; 58:09-1:30:01 · E010-001 · Dr. Dietrich Klinghardt; Maria Crisler\n\n## Unabhängige Evidenzeinordnung\nKeine unabhängige kontrollierte Humanstudie für Hydrogele, Robotik, Organschutz oder Krankheitsendpunkte; Hersteller-/Sprecherclaim.\n\n## Sicherheit · BEACHTEN\nEtikettendosis nicht durch Videotitration überschreiten; Durchfall/Ausscheidungsbilder nicht automatisch als Entgiftung deuten.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('71b7897b-e10e-546d-a8d0-b1b28da93c68', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-disulfiram-titration', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Disulfiram bei Lyme: langsame Aufdosierung, lange Dauer und 500-mg-Warnung', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-disulfiram-titration', 'unknown', 'Folge 019 1:00:02-1:03:23 E019-025; Folge 019 1:03:23-1:04:56 E019-026', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-disulfiram-titration","aliases":["Disulfiram bei Lyme: langsame Aufdosierung, lange Dauer und 500-mg-Warnung"],"tags":["Erfahrungsheilkunde","Folge 019","Interne Prüfung","Klinghardt-Talks","Pathogene und Infektionen","Quellenkarte","Sprecher: BW","Sprecher: BW; DK","Sprecheraussage"],"therapeutic_topics":["Pathogene und Infektionen"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Disulfiram nur ärztlich, nach Kontraindikations-/Interaktionsprüfung, strikter Alkoholmeidung und mit Leber-, neurologischer und psychiatrischer Überwachung. Eine Verschlechterung nicht automatisch als heilende Herxheimer-Reaktion deuten [S18, S19, S21].","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E019-025, E019-026; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nWeitkus habe zuerst ihren Sohn mit Disulfiram behandelt und anfangs zu hoch dosiert. Starke als Herxheimer-Reaktion gedeutete neurologische und psychische Symptome hätten Ausschleichen, Absetzen und Neubewertung erfordert. Danach sei sie mit einer Vierteltablette alle vier, drei, zwei Tage und schließlich täglich vorgegangen. Sie gebe höchstens 250 mg, arbeite mit Pausen und zwei bis drei Wiederholungszyklen und nennt eine Halbwertszeit von 14 Tagen beziehungsweise vierwöchigen Abbau. Bei schwer kranken, älteren oder multipel belasteten Patienten starte sie mit 5 mg und steigere über 10, 15 und 20 mg, häufig bis 125, bei Verträglichkeit bis 250 mg. Zusätzlich behauptet sie, Lyme verlange doppelt so hohe Antibiotikadosen wie andere Infektionen.\n\n## Genannte Mittel oder Verfahren\n- Niedrig beginnende, zyklisch aufdosierte Disulfiram-Off-Label-Therapie\n- Langfristiges niedrig dosiertes Disulfiram; 500 mg ausdrücklich als schlecht verträglich beschrieben\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nVierteltablette alle 4, dann 3, dann 2 Tage und schließlich täglich; Start 5 mg; Steigerung über 10, 15 und 20 mg; häufig 125 mg, höchstens 250 mg; Pausen und 2-3 Zyklen. 500 mg werden wegen schwerer neuropsychiatrischer Reaktionen verworfen; behauptete Gesamtdauer 1-2 Jahre.\n\n## Sprecher und Fundstellen\n- Folge 019 · 1:00:02-1:03:23 · E019-025 · BW\n- Folge 019 · 1:03:23-1:04:56 · E019-026 · BW; DK\n\n## Unabhängige Evidenzeinordnung\nDie 2025-Pilotstudie mit neun Ausgewerteten zeigte mögliche Symptomssignale, konnte Wirksamkeit aber ohne Placebokontrolle nicht beurteilen; nur drei schlossen die Behandlung vollständig ab, fünf stoppten wegen Reaktionen/Laborwerten [S18]. Retrospektive Serien sind hypothesengenerierend [S20]. Die starre Halbwertszeitangabe wird im Track nicht belegt.\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Disulfiram nur ärztlich, nach Kontraindikations-/Interaktionsprüfung, strikter Alkoholmeidung und mit Leber-, neurologischer und psychiatrischer Überwachung. Eine Verschlechterung nicht automatisch als heilende Herxheimer-Reaktion deuten [S18, S19, S21].\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('20e451aa-3ea9-5e71-b90c-ba724af155ec', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-erythromycin-prolotherapy', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Erythromycin 500 mg viermal täglich, Prolotherapie und Behördenkonflikt', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-erythromycin-prolotherapy', 'unknown', 'Folge 020 16:26-18:54 E020-008', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-erythromycin-prolotherapy","aliases":["Erythromycin 500 mg viermal täglich, Prolotherapie und Behördenkonflikt"],"tags":["Erfahrungsheilkunde","Folge 020","Interne Prüfung","Klinghardt-Talks","Pathogene und Infektionen","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Pathogene und Infektionen"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Regime nicht übernehmen. Erythromycin kann QT-Verlängerung, Torsade, Hepatotoxizität, C.-difficile-Kolitis und zahlreiche CYP3A-Interaktionen verursachen [S26]. Injektionen bergen Blutungs-, Infektions-, Nerven- und Fehlplatzierungsrisiken.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E020-008; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt bezeichnet Doxycyclin rückblickend als nahezu nutzlos und nennt Erythromycin 500 mg viermal täglich als damalige besonders schöne Behandlung von Lyme beziehungsweise chronischem Kreuzschmerz. Er habe es mit Prolotherapie zur Reparatur des Schadens kombiniert und sei damit weltweit bekannt geworden. Wegen Konflikten mit dem Medical Board und wöchentlichen Untersuchungen durch mehrere Behörden, darunter von ihm genannte FDA- und CIA-Agenten, habe er letztlich geschwiegen und sei nach Seattle umgezogen, um in einer damals kleineren Region weniger aufzufallen.\n\n## Genannte Mittel oder Verfahren\n- Orales Erythromycin plus Prolotherapie bei als infektiös gedeutetem Kreuzschmerz\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nErythromycin 500 mg viermal täglich, insgesamt 2.000 mg/Tag; Prolotherapielösung, Injektionsorte, Frequenz und Dauer fehlen.\n\n## Sprecher und Fundstellen\n- Folge 020 · 16:26-18:54 · E020-008 · DK\n\n## Unabhängige Evidenzeinordnung\nLeitlinien empfehlen bei Lyme je nach Manifestation Doxycyclin, Amoxicillin, Cefuroxim oder bestimmte Beta-Laktame; Erythromycin ist keine Standardtherapie für unselektierten Kreuzschmerz [S04-S06]. Prolotherapie allein war im Cochrane-Review nicht wirksamer als Kontrollinjektionen; Kombinationsergebnisse waren durch Begleittherapien verzerrt [S25].\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Regime nicht übernehmen. Erythromycin kann QT-Verlängerung, Torsade, Hepatotoxizität, C.-difficile-Kolitis und zahlreiche CYP3A-Interaktionen verursachen [S26]. Injektionen bergen Blutungs-, Infektions-, Nerven- und Fehlplatzierungsrisiken.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('c4ed816f-0a8c-5191-a35c-85693d70e399', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-herbs-lyme-bartonella-babesia', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Explizite Kräuterdosen für Lyme, Bartonella und Babesiose', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-herbs-lyme-bartonella-babesia', 'unknown', 'Folge 020 1:01:59-1:02:40 E020-029', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-herbs-lyme-bartonella-babesia","aliases":["Explizite Kräuterdosen für Lyme, Bartonella und Babesiose"],"tags":["Erfahrungsheilkunde","Folge 020","Interne Prüfung","Klinghardt-Talks","Pflanzenheilkunde","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Pflanzenheilkunde"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Produkte und Dosen nicht übernehmen. Ein Teelöffel ist ohne Konzentration keine reproduzierbare Wirkstoffdosis. Wahrscheinlich Artemisinin kann Produkt-, Leber-, Blutbild- und Interaktionsrisiken haben; bestätigte Babesiose kann hämolytisch und schwer verlaufen und benötigt ärztliche Diagnostik.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E020-029; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nZum Abschluss wiederholt Klinghardt seine hauptsächlichen pflanzlichen Behandlungen. Für Lyme nennt er einen nicht näher zusammengesetzten ''Cocktail'' mit einem Teelöffel zweimal täglich. Für Bartonella nennt er ''Lymphatic Detox'' ebenfalls einen Teelöffel zweimal täglich. Für Babesiose nennt er ein im Auto-Track als ''Otin'' oder ähnlich gehörtes Pulver, kontextnah wahrscheinlich Artemisinin: Die zugrunde liegende Malariaentdeckung habe zehn Jahre zuvor den Medizin-Nobelpreis erhalten. Davon gebe er etwa 500 mg täglich und gehe langsam und stetig vor.\n\n## Genannte Mittel oder Verfahren\n- Unbekannter Lyme-''Cocktail''; Lymphatic Detox; wahrscheinlich Artemisinin-Pulver bei Babesiose\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nCocktail 1 TL zweimal täglich; Lymphatic Detox 1 TL zweimal täglich; wahrscheinlich Artemisinin-Pulver etwa 500 mg täglich.\n\n## Sprecher und Fundstellen\n- Folge 020 · 1:01:59-1:02:40 · E020-029 · DK\n\n## Unabhängige Evidenzeinordnung\nTu Youyou erhielt den Nobelpreis für Artemisinin-basierte Malariatherapie, nicht für Lyme oder Babesiose [S19]. Für symptomatische Babesiose empfiehlt CDC definierte verschreibungspflichtige Kombinationen, meist Atovaquon plus Azithromycin; die genannte Pulvermonotherapie ist kein Standard [S10]. Botanische Borrelienbefunde sind in vitro und keine klinische Dosisstudie [S17].\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Produkte und Dosen nicht übernehmen. Ein Teelöffel ist ohne Konzentration keine reproduzierbare Wirkstoffdosis. Wahrscheinlich Artemisinin kann Produkt-, Leber-, Blutbild- und Interaktionsrisiken haben; bestätigte Babesiose kann hämolytisch und schwer verlaufen und benötigt ärztliche Diagnostik.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('2b63feb5-2887-5660-bc29-7986eb521171', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-artesunate-lung-fibrosis', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Pulmonale Hypertonie, Bronchiektasen und Artesunat gegen Lungenfibrose', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-artesunate-lung-fibrosis', 'unknown', 'Folge 022 26:44-29:22 E022-014', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-artesunate-lung-fibrosis","aliases":["Pulmonale Hypertonie, Bronchiektasen und Artesunat gegen Lungenfibrose"],"tags":["Erfahrungsheilkunde","Erkrankungen und Symptome","Folge 022","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Erkrankungen und Symptome"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Keine artesunathaltige Injektion außerhalb zugelassener Indikation/Qualität. Dyspnoe, Synkope, Brustschmerz oder Hypoxie pneumologisch/kardiologisch dringlich abklären.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E022-014; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nBei einer Frage zu pulmonaler Hypertonie und Bronchiektasen erklärt Klinghardt korrekt verkürzt, vernarbte Lungenerkrankung könne den pulmonalen Gefäßwiderstand erhöhen. Als außerhalb der USA verfügbare ''schöne Lösung'' für Lungenfibrose nennt er jedoch wahrscheinlich Artesunat: eine intramuskuläre Injektion von 60 mg einmal wöchentlich sei für die meisten Patienten kurativ. Die FDA habe injizierbares Artesunat kurz vor COVID verboten; in Deutschland könne er es frei verwenden, während Menschen in den USA zum Tod durch Lungenfibrose verurteilt seien. Außerdem könne jede menschliche Diagnose, ausdrücklich auch pulmonale Hypertonie, durch Lyme verursacht werden.\n\n## Genannte Mittel oder Verfahren\n- Wahrscheinlich Artesunat intramuskulär gegen Lungenfibrose; Lyme-Ursachensuche\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\n60 mg intramuskulär einmal pro Woche; Dauer nicht genannt.\n\n## Sprecher und Fundstellen\n- Folge 022 · 26:44-29:22 · E022-014 · DK\n\n## Unabhängige Evidenzeinordnung\nPulmonale Hypertonie hat fünf große Ursachenklassen und benötigt gezielte Diagnostik [S15]. Das FDA-Label betrifft intravenöses Artesunat bei schwerer Malaria, nicht intramuskuläre Wochenbehandlung der Lungenfibrose [S16]. Eine Heilungsrate für Lungenfibrose wird nicht belegt.\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Keine artesunathaltige Injektion außerhalb zugelassener Indikation/Qualität. Dyspnoe, Synkope, Brustschmerz oder Hypoxie pneumologisch/kardiologisch dringlich abklären.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('9a20bd2a-01dd-59e1-b4da-eafb47b92375', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-dhea-pulmonary-hypertension', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: IV-Wasserstoffperoxid und 600 mg DHEA bei Lungenerkrankungen', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-dhea-pulmonary-hypertension', 'unknown', 'Folge 022 30:13-32:39 E022-016', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-dhea-pulmonary-hypertension","aliases":["IV-Wasserstoffperoxid und 600 mg DHEA bei Lungenerkrankungen"],"tags":["Erfahrungsheilkunde","Erkrankungen und Symptome","Folge 022","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Erkrankungen und Symptome"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Kein IV-H2O2 und keine 600-mg-DHEA-Selbstanwendung. Gasembolie, Hämolyse, Gefäß-/Organschäden und schwere Hormonwirkungen sind möglich.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E022-016; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nBei Bronchiektasen nennt Klinghardt intravenöses H2O2/Wasserstoffperoxid und weitere schleimlösende Maßnahmen. Oxidative Abtötungsmittel sollten über das Blut die Lunge erreichen, ohne sie zu verletzen; Lyme müsse immer geprüft werden. Als ''vergessene'', erwägenswerte Therapie der pulmonalen Hypertonie berichtet er von einer Frau, die vor 25 bis 30 Jahren unter ungefähr 600 mg DHEA innerhalb von zwei bis drei Monaten genesen sei, ohne Akne oder Bartwuchs. Später sei auf ungefähr 100 mg täglich reduziert worden.\n\n## Genannte Mittel oder Verfahren\n- Intravenöses Wasserstoffperoxid; hoch dosiertes DHEA\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nDHEA etwa 600 mg, später etwa 100 mg täglich; IV-H2O2 ohne Konzentration, Volumen oder Dauer.\n\n## Sprecher und Fundstellen\n- Folge 022 · 30:13-32:39 · E022-016 · DK\n\n## Unabhängige Evidenzeinordnung\nWasserstoffperoxid ist ein starkes Oxidationsmittel, kein etabliertes IV-Lungenmittel [S17]. DHEA ist ein Steroidhormon; belastbare Evidenz für pulmonale Hypertonie fehlt, während hormonelle, onkologische, lipidbezogene und psychiatrische Risiken bestehen [S18].\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Kein IV-H2O2 und keine 600-mg-DHEA-Selbstanwendung. Gasembolie, Hämolyse, Gefäß-/Organschäden und schwere Hormonwirkungen sind möglich.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('73f62a86-badb-5a02-a33d-3b928fe4f8bc', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-hyaluronic-acid-lyme', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Floaters als Borrelien, Hyaluronsäure-Köderdosierung und MS-Myelinclaim', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-hyaluronic-acid-lyme', 'unknown', 'Folge 022 40:06-42:27 E022-020', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-hyaluronic-acid-lyme","aliases":["Floaters als Borrelien, Hyaluronsäure-Köderdosierung und MS-Myelinclaim"],"tags":["Erfahrungsheilkunde","Folge 022","Interne Prüfung","Klinghardt-Talks","Pathogene und Infektionen","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Pathogene und Infektionen"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Neue Lichtblitze, Rußregen, Gesichtsfeldausfall oder viele neue Floaters sofort augenärztlich abklären. MS-Therapie nicht für ein unvalidiertes Cocktailprotokoll absetzen.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E022-020; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt behauptet, wurmähnliche Glaskörpertrübungen seien Borrelien im hyaluronsäurereichen Auge. Sublinguale Hyaluronsäure locke Spirochäten nach einer halben Stunde aus dem Versteck, worauf der Cocktail sie töte. Später mische man beides in einem Gefäß: Start mit etwa 1 bis 2 ml zweimal täglich in Wasser, Steigerung auf ungefähr 10 bis 12 ml zweimal täglich. Schwere Autoimmunerkrankungen wie MS entstünden überwiegend durch stationäre Lymeformen im Myelin; Hyaluronsäure lasse die angeblichen Eier schlüpfen und herausschwimmen.\n\n## Genannte Mittel oder Verfahren\n- Sublinguale Hyaluronsäure plus Lyme-Cocktail als Köder-/Abtötungsprotokoll\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nZunächst etwa 1-2 ml zweimal täglich, Steigerung auf etwa 10-12 ml zweimal täglich; Konzentration und Inhaltsstoffe fehlen.\n\n## Sprecher und Fundstellen\n- Folge 022 · 40:06-42:27 · E022-020 · DK\n\n## Unabhängige Evidenzeinordnung\nGlaskörpertrübungen haben zahlreiche ophthalmologische Ursachen; der Track zeigt keine Mikroskopie/PCR. MS ist eine immunvermittelte demyelinisierende Erkrankung und nicht überwiegend als schlüpfende Lymeform belegt [S14, S24]. In-vitro-Pflanzendaten validieren weder Köder noch Dosis [S20].\n\n## Sicherheit · BEACHTEN\nNeue Lichtblitze, Rußregen, Gesichtsfeldausfall oder viele neue Floaters sofort augenärztlich abklären. MS-Therapie nicht für ein unvalidiertes Cocktailprotokoll absetzen.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('df2e538c-a293-516b-92f4-8cde7b7f033d', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-lithium-memory', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Gedächtnis nach COVID/Lyme und 150 mg Lithiumorotat', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-lithium-memory', 'unknown', 'Folge 022 46:01-47:28 E022-022', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-lithium-memory","aliases":["Gedächtnis nach COVID/Lyme und 150 mg Lithiumorotat"],"tags":["Erfahrungsheilkunde","Erkrankungen und Symptome","Folge 022","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Erkrankungen und Symptome"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: 150 mg nicht übernehmen. Lithium kann Nieren, Schilddrüse, Herz und Nervensystem schädigen und interagiert unter anderem mit NSAID, ACE-Hemmern und Diuretika; Serum-/Organmonitoring gehört in ärztliche Führung.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E022-022; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nAuf eine Frage zu seit Lyme und COVID bestehenden Kurz- und Langzeitgedächtnisstörungen nennt Klinghardt ein Buch von Michael Nehls. COVID habe den Hippocampus gezielt. Moderat hoch dosiertes Lithiumorotat verbessere dies; für die meisten nennt er ungefähr 150 mg und verweist auf 120-mg-Tabletten plus 20-mg-Kapseln, während früher bei autistischen Kindern 3 bis 5 mg verwendet worden seien. Die Zahlen und ob Salz- oder Elementarlithium gemeint ist, bleiben unklar.\n\n## Genannte Mittel oder Verfahren\n- Lithiumorotat gegen Gedächtnisstörungen nach COVID\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nEtwa 150 mg; Produkte 120 mg plus 20 mg; früher 3-5 mg bei autistischen Kindern. Elementarlithium nicht angegeben.\n\n## Sprecher und Fundstellen\n- Folge 022 · 46:01-47:28 · E022-022 · DK\n\n## Unabhängige Evidenzeinordnung\nLithiumorotat ist kein validiertes Standardprotokoll zur kognitiven Rehabilitation. Ein Fallbericht zeigt akute Toxizität eines Internet-Lithiumorotatprodukts und verdeutlicht die zwingende Unterscheidung von Salz- und Elementarmenge [S25].\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: 150 mg nicht übernehmen. Lithium kann Nieren, Schilddrüse, Herz und Nervensystem schädigen und interagiert unter anderem mit NSAID, ACE-Hemmern und Diuretika; Serum-/Organmonitoring gehört in ärztliche Führung.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('7108464f-da73-5dce-891b-c5c483aad5fa', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-liposorb-herbal-iv', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: LipoSorb und Herbal IV', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-liposorb-herbal-iv', 'unknown', 'Folge 007 27:39-30:04 E007-010', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-liposorb-herbal-iv","aliases":["LipoSorb und Herbal IV"],"tags":["Erfahrungsheilkunde","Folge 007","Interne Prüfung","Klinghardt-Talks","Pflanzenheilkunde","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Michele Milligan (Einzelzuordnung nicht strukturell kodiert)","Sprecheraussage"],"therapeutic_topics":["Pflanzenheilkunde"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. IV-Gleichwertigkeit nicht erfassen. Erhoehte Bioverfuegbarkeit koennte auch Toxizitaet und Interaktionen steigern; Formulierungs- und PK-Daten verlangen.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E007-010; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nEin Teil Phospholipid/LipoSorb auf sechs Teile Kraeuter verbessere Aufnahme und Penetration in Gehirn, Augen, Nieren und Knochen. Die oral getrunkene Mischung wirke praktisch wie eine IV-Infusion oder tiefgreifender; IV-Effekte seien teils Placebo.\n\n## Genannte Mittel oder Verfahren\n- LipoSorb/Phosphatidylcholin und Kraeutermischung.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nIm Video genanntes Mischungsverhältnis: ungefähr 1 Teil LipoSorb/Phosphatidylcholin auf 6 Teile Kräutermischung. Absolute Menge und Einnahmehäufigkeit werden im Video nicht genannt.\n\n## Sprecher und Fundstellen\n- Folge 007 · 27:39-30:04 · E007-010 · Dr. Dietrich Klinghardt; Michele Milligan (Einzelzuordnung nicht strukturell kodiert)\n\n## Unabhängige Evidenzeinordnung\nEinfaches Mischen beweist weder Vesikelbildung noch Einkapselung, Stabilitaet oder Organverteilung. Selbst charakterisierte orale liposomale Vitamin-C-Formulierungen erreichten in einer kleinen Studie weniger Exposition als IV-Vitamin C; Uebertragung auf Kraeuter ist unzulaessig.\n\n## Sicherheit · BEACHTEN\nIV-Gleichwertigkeit nicht erfassen. Erhoehte Bioverfuegbarkeit koennte auch Toxizitaet und Interaktionen steigern; Formulierungs- und PK-Daten verlangen.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('01157cf6-a0e9-550a-8f27-b71ff14ebeb6', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-streptococcus-potencies', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Sechs Potenzen und mehrmonatige Eskalation', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-streptococcus-potencies', 'unknown', 'Folge 006 49:51-51:20; 59:49-1:02:29 E006-012', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-streptococcus-potencies","aliases":["Sechs Potenzen und mehrmonatige Eskalation"],"tags":["Erfahrungsheilkunde","Folge 006","Interne Prüfung","Klinghardt-Talks","Pathogene und Infektionen","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Dr. Andreas Tilch (Einzelzuordnung nicht strukturell kodiert)","Sprecheraussage"],"therapeutic_topics":["Pathogene und Infektionen"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Videodosen nur als speaker_reported_unverified erfassen. Keine automatische Dosierungsregel. Subjektive Krisen, Visionen, Rueckenschmerz oder Migraene nicht als Dosissteigerungssignal verwenden.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E006-012; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nVerwendet werden 10C, 40C, 220C, 1.3M, 7.78M und 46.66M. Meist soll etwa alle drei bis vier Wochen bis zu einem Plateau gesteigert werden; nach rund sechs Monaten werde die hoechste, spirituellste Stufe erreicht.\n\n## Genannte Mittel oder Verfahren\n- Sechsstufiges Streptococcus-pyogenes-Tilch-Set.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nIm Video: etwa fuenf Globuli; bei Reaktion nur einmal und nach zwei Wochen erneut, sonst wiederholt bis 2x/Tag. Tilch berichtet 46.66M morgens und abends seit etwa drei Jahren.\n\n## Sprecher und Fundstellen\n- Folge 006 · 49:51-51:20; 59:49-1:02:29 · E006-012 · Dr. Dietrich Klinghardt; Dr. Andreas Tilch (Einzelzuordnung nicht strukturell kodiert)\n\n## Unabhängige Evidenzeinordnung\nDie Produktoptionen sind verifizierbar, das klinische Schema nicht. Es gibt keine Dosisfindungsstudie, keine Pharmakokinetik und keinen Beleg, dass hoehere Potenzen tiefere, spirituelle oder staerkere Wirkungen haben. Ab C12 ist Ausgangsmolekuelnachweis in ueblicher Dosis extrem unwahrscheinlich.\n\n## Sicherheit · BEACHTEN\nVideodosen nur als speaker_reported_unverified erfassen. Keine automatische Dosierungsregel. Subjektive Krisen, Visionen, Rueckenschmerz oder Migraene nicht als Dosissteigerungssignal verwenden.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('45acac91-9a1c-5a9d-9bfc-666f71a18a87', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-dapson-protection-glutathione', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Anemie, Methaemoglobin und behauptete Schutzmassnahmen', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-dapson-protection-glutathione', 'unknown', 'Folge 003 17:26-21:18 E003-002', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-dapson-protection-glutathione","aliases":["Anemie, Methaemoglobin und behauptete Schutzmassnahmen"],"tags":["Erfahrungsheilkunde","Folge 003","Interne Prüfung","Klinghardt-Talks","Pathogene und Infektionen","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Dr. Richard Horowitz (Einzelzuordnung nicht strukturell kodiert)","Sprecheraussage"],"therapeutic_topics":["Pathogene und Infektionen"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Die Aussage ''alles reversibel'' ist falsch: Todesfaelle durch Blutdyskrasien, DRESS und Leberversagen sind beschrieben. Methylenblau ist bei G6PD-Mangel kontraindiziert und kann mit SSRI/SNRI/MAO-Hemmern, Bupropion, Buspiron, Mirtazapin, Clomipramin, bestimmten Opioiden, Linezolid oder Dextromethorphan ein schweres Serotoninsyndrom ausloesen.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E003-002; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nAls DO-NO-HARM-Schema werden Herxheimer-Reaktion, Anemie, Methaemoglobinaemie und Rash besprochen. Ein durchschnittlicher Hb-Abfall um etwa 4 g/dl wird als reversibel dargestellt; Methaemoglobinwerte von meist 5-6%, gelegentlich bis 10%, werden verharmlost.\n\n## Genannte Mittel oder Verfahren\n- Folinsaeure/Leucovorin, L-Methylfolat, Folsauere; Glutathion, Vitamin C, Vitamin E, NADH und orales Methylenblau. Gegen Entzuendung NAC, Alpha-Liponsaeure, Curcumin, Brokkolisamenextrakt und Resveratrol.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nGlutathion bis 2.000 mg mehrmals taeglich; exakte Dosen der weiteren Stoffe fehlen. Die Folatmenge und Methylenblau-Dosis werden im Video nicht genannt.\n\n## Sprecher und Fundstellen\n- Folge 003 · 17:26-21:18 · E003-002 · Dr. Dietrich Klinghardt; Dr. Richard Horowitz (Einzelzuordnung nicht strukturell kodiert)\n\n## Unabhängige Evidenzeinordnung\nDie bekannten Mechanismen und Toxizitaeten von Dapson sind gut belegt. Die konkrete Supplementkombination zur Verhinderung dieser Risiken ist nicht durch offizielle Labels oder kontrollierte Studien abgesichert.\n\n## Sicherheit · HOCH\nDie Aussage ''alles reversibel'' ist falsch: Todesfaelle durch Blutdyskrasien, DRESS und Leberversagen sind beschrieben. Methylenblau ist bei G6PD-Mangel kontraindiziert und kann mit SSRI/SNRI/MAO-Hemmern, Bupropion, Buspiron, Mirtazapin, Clomipramin, bestimmten Opioiden, Linezolid oder Dextromethorphan ein schweres Serotoninsyndrom ausloesen.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('89433a4b-ac54-50b8-aaa6-91d39ae17e2a', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-rectal-melatonin', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Rektales Hochdosis-Melatonin, Krebsdosis und Schwangerschaftsprotokoll', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-rectal-melatonin', 'unknown', 'Folge 016 12:06-13:18 E016-006', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-rectal-melatonin","aliases":["Rektales Hochdosis-Melatonin, Krebsdosis und Schwangerschaftsprotokoll"],"tags":["Erfahrungsheilkunde","Erkrankungen und Symptome","Folge 016","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Erkrankungen und Symptome"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: 50-200 mg rektales Melatonin, besonders bei Krebs oder Schwangerschaft, nicht selbst anwenden. Sedierung, Sturz, Verkehrstüchtigkeit, Blutverdünner, Epilepsie, endokrine Effekte, Produktreinheit und fetale Risiken ärztlich prüfen [S03, S06]. Chlorella ersetzt keine pränatale Versorgung.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E016-006; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nDie meisten seiner Patienten erhielten abends ein Melatoninzäpfchen mit 50 mg; bei Krebserkrankungen gebe man bis 200 mg. Melatonin schütze vor Quecksilber- und Bleivergiftung, lindere Symptome, mache Blei unschädlicher, unterstütze die Ausleitung und schütze vor Herbiziden einschließlich Glyphosat. Mutterleib und Fötus könnten so vor mütterlichen Schadstoffen geschützt werden. Klinghardt sagt, jede Schwangerschaft werde in seiner Arbeit mit Chlorella und hohen Melatonindosen begleitet.\n\n## Genannte Mittel oder Verfahren\n- Melatonin-Zäpfchen; Chlorella; behauptete Metall-/Herbizidprotektion in Schwangerschaft und Krebs\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nMelatonin meist 50 mg rektal am Abend; bei Krebs bis 200 mg. Chlorella- und Schwangerschaftsdosis fehlen.\n\n## Sprecher und Fundstellen\n- Folge 016 · 12:06-13:18 · E016-006 · DK\n\n## Unabhängige Evidenzeinordnung\nZugelassene Melatoninanwendungen liegen indikationsbezogen bei deutlich niedrigeren Dosen, etwa 2 mg retardiert [S05]. Langzeit- und Hochdosisdaten sind begrenzt [S03]; Krebsnutzen bleibt sehr unsicher [S04]. Der NHS empfiehlt Melatonin in der Schwangerschaft gewöhnlich nicht, weil Daten zum Kind fehlen [S06]. Eine klinische Metall- oder Glyphosatausleitung ist damit nicht belegt.\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: 50-200 mg rektales Melatonin, besonders bei Krebs oder Schwangerschaft, nicht selbst anwenden. Sedierung, Sturz, Verkehrstüchtigkeit, Blutverdünner, Epilepsie, endokrine Effekte, Produktreinheit und fetale Risiken ärztlich prüfen [S03, S06]. Chlorella ersetzt keine pränatale Versorgung.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('74ea853e-f87a-59a8-80d6-ab2481143628', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-apolactoferrin', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Apolactoferrin / Lactoferrin + Copper1', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-apolactoferrin', 'unknown', 'Folge 010 1:01:58-1:32:42 E010-003', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-apolactoferrin","aliases":["Apolactoferrin / Lactoferrin + Copper1"],"tags":["Erfahrungsheilkunde","Folge 010","Interne Prüfung","Klinghardt-Talks","Medikamente und Nährstoffe","Quellenkarte","Sprecher: Maria Crisler; Dr. Dietrich Klinghardt","Sprecheraussage"],"therapeutic_topics":["Medikamente und Nährstoffe"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Laborindikation, Milchproteinallergie, Eisen-/Kupferstatus, Leber/Niere, Schwangerschaft und Wilson-Krankheit beachten.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E010-003; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nEisen binden/umverteilen, Anämie und angebliches Eisenoxidnetz adressieren\n\n## Genannte Mittel oder Verfahren\n- Apolactoferrin / Lactoferrin + Copper1\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nIm Gespräch: 300 mg; Probe ungefähr 40 % Apo-Anteil, geplante Formel 70 % Apo-Anteil. Eine Einnahmehäufigkeit wird im Gespräch nicht eindeutig genannt.\n\n## Sprecher und Fundstellen\n- Folge 010 · 1:01:58-1:32:42 · E010-003 · Maria Crisler; Dr. Dietrich Klinghardt\n\n## Unabhängige Evidenzeinordnung\nBegrenzte, heterogene Anämieforschung; keine Wirkung auf angebliches Eisenoxid-/Graphennetz. Aktuelles Etikett bestätigt keinen 70-%-Apo-Anteil.\n\n## Sicherheit · HOCH\nLaborindikation, Milchproteinallergie, Eisen-/Kupferstatus, Leber/Niere, Schwangerschaft und Wilson-Krankheit beachten.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('2d74bc0f-62eb-553d-bd03-3e7e31ddb31d', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-niacin-cholesterol', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Cholesterin: Fischol, Retard-Niacin und Chlorella', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-niacin-cholesterol', 'unknown', 'Folge 005 05:03-07:31 E005-004', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-niacin-cholesterol","aliases":["Cholesterin: Fischol, Retard-Niacin und Chlorella"],"tags":["Erfahrungsheilkunde","Erkrankungen und Symptome","Folge 005","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt","Sprecheraussage"],"therapeutic_topics":["Erkrankungen und Symptome"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. 1.500 mg/Tag ist eine pharmakologische Hochdosis und keine harmlose Nahrungsergaenzung. Leberwerte, Glukose, Harnsaeure, Blutung und Interaktionen beachten. Langsam freisetzendes Niacin verhindert weder Flush sicher noch Lebertoxizitaet. Hochdosiertes Omega-3 kann Vorhofflimmern und Blutungen beguenstigen.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E005-004; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nModerates Fischol und mindestens 500 mg wachsgebundenes langsam freisetzendes Niacin dreimal taeglich sollen Cholesterin fast immer senken, ohne Flush. Chlorella wird ebenfalls als Cholesterinsenker genannt.\n\n## Genannte Mittel oder Verfahren\n- Omega-3-Fettsaeuren, Retard-/Wax-Matrix-Niacin und Chlorella; Bewegung und Ernaehrung.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nNiacin 500 mg dreimal taeglich, insgesamt 1.500 mg/Tag. Fischol- und Chlorelladosen fehlen.\n\n## Sprecher und Fundstellen\n- Folge 005 · 05:03-07:31 · E005-004 · Dr. Dietrich Klinghardt\n\n## Unabhängige Evidenzeinordnung\nNiacin verbessert Lipidwerte, brachte in AIM-HIGH und HPS2-THRIVE zusaetzlich zu Statinen aber keinen kardiovaskulaeren Vorteil und mehr Nebenwirkungen. Retardformen koennen besonders hepatotoxisch sein. Reines verschreibungspflichtiges EPA zeigte nur in einer definierten Hochrisikogruppe Nutzen; EPA/DHA-Gemische sind nicht gleichwertig. Chlorella zeigte in kleinen RCTs geringe Surrogatveraenderungen, keine Ereignisreduktion.\n\n## Sicherheit · HOCH\n1.500 mg/Tag ist eine pharmakologische Hochdosis und keine harmlose Nahrungsergaenzung. Leberwerte, Glukose, Harnsaeure, Blutung und Interaktionen beachten. Langsam freisetzendes Niacin verhindert weder Flush sicher noch Lebertoxizitaet. Hochdosiertes Omega-3 kann Vorhofflimmern und Blutungen beguenstigen.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('f06c892c-cdee-5b1e-9d4f-ce10290737de', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-insuless', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: InsuLessTM', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-insuless', 'unknown', 'Folge 010 1:02:21-1:34:48 E010-002', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-insuless","aliases":["InsuLessTM"],"tags":["Erfahrungsheilkunde","Folge 010","Interne Prüfung","Klinghardt-Talks","Medikamente und Nährstoffe","Quellenkarte","Sprecher: Maria Crisler; Dr. Dietrich Klinghardt","Sprecheraussage"],"therapeutic_topics":["Medikamente und Nährstoffe"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Video, Website und Flaschenetikett widersprechen sich; keine Ableitung ohne Chargenetikett und Interaktionsprüfung.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E010-002; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nNieren-/Antioxidanz-/Stoffwechselunterstützung; Glutathion; leitfähige Fasern; breite Krankheitsbezüge\n\n## Genannte Mittel oder Verfahren\n- InsuLessTM\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nIm Gespräch: 5 Tropfen zweimal täglich.\n\n## Sprecher und Fundstellen\n- Folge 010 · 1:02:21-1:34:48 · E010-002 · Maria Crisler; Dr. Dietrich Klinghardt\n\n## Unabhängige Evidenzeinordnung\nKeine unabhängige klinische Evidenz für breite Stoffwechsel-, Nieren- oder neurologische Krankheitsclaims; Patent/Preis beweisen keine Wirkung.\n\n## Sicherheit · BEACHTEN\nVideo, Website und Flaschenetikett widersprechen sich; keine Ableitung ohne Chargenetikett und Interaktionsprüfung.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('fe8a2566-0a95-56a6-8f5b-db4be2e6e1fd', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-copper', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Kupfer', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-copper', 'unknown', 'Folge 010 1:02:39-1:32:42 E010-004', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-copper","aliases":["Kupfer"],"tags":["Erfahrungsheilkunde","Folge 010","Interne Prüfung","Klinghardt-Talks","Medikamente und Nährstoffe","Quellenkarte","Sprecher: Maria Crisler","Sprecheraussage"],"therapeutic_topics":["Medikamente und Nährstoffe"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Gesamtzufuhr und Störungen des Kupferstoffwechsels prüfen; keine pauschale Supplementierung.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E010-004; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nEisen aus Leber mobilisieren/transportieren\n\n## Genannte Mittel oder Verfahren\n- Kupfer\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nSpur Kupfer; später 3 mg genannt\n\n## Sprecher und Fundstellen\n- Folge 010 · 1:02:39-1:32:42 · E010-004 · Maria Crisler\n\n## Unabhängige Evidenzeinordnung\nKeine Evidenz für Umfunktionierung eines behaupteten Eisenoxidnetzes; 3 mg liegt über der Erwachsenen-RDA, wenn auch unter dem US-UL.\n\n## Sicherheit · BEACHTEN\nGesamtzufuhr und Störungen des Kupferstoffwechsels prüfen; keine pauschale Supplementierung.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('89027e4e-2126-5f70-a0e4-b5ca65f427d5', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-photonwave-aluminium', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Zwölf Minuten PhotonWave und behauptete Aluminium-Ausscheidung', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-photonwave-aluminium', 'unknown', 'Folge 021 41:35-43:17 E021-024', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-photonwave-aluminium","aliases":["Zwölf Minuten PhotonWave und behauptete Aluminium-Ausscheidung"],"tags":["Ausleitung","Erfahrungsheilkunde","Folge 021","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Ausleitung"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Keine Metallausleitung aus einem einzelnen Urinanstieg ableiten. Bei echter Exposition toxikologische Anamnese, validierte Proben und Nierenfunktion verwenden.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E021-024; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt zeigt eine Uringrafik nach einer einzigen zwölfminütigen PhotonWave-Behandlung. Aluminium sei als Vorlage mit Lochplatte genutzt und Detox- sowie Allergieprogramm, anschließend weitere ASR-unklare Heilmittel ohne Loch, durchgeführt worden. Zwölf Stunden später sei eine riesige Aluminiummenge ausgeschieden worden; nach 24 Stunden habe der Effekt noch angehalten.\n\n## Genannte Mittel oder Verfahren\n- PhotonWave mit Aluminiumvorlage, Lochplatte, Detox-/Allergieprogramm und unklaren Zusatzmitteln\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nEine 12-minütige Sitzung; Urinmessungen nach ungefähr 12 und 24 Stunden.\n\n## Sprecher und Fundstellen\n- Folge 021 · 41:35-43:17 · E021-024 · DK\n\n## Unabhängige Evidenzeinordnung\nUrinmetalle hängen unter anderem von Konzentrationsbezug, Sammelzeit, Nierenfunktion, Exposition und Provokation ab. ACMT warnt vor post-chelatorischen Provokationstests wegen fehlender validierter Referenzbereiche und Fehlinterpretation [S16]. Der Track zeigt keine Kontrolle, Massenbilanz oder unabhängige Replikation einer Lichtausleitung.\n\n## Sicherheit · HOCH\nKeine Metallausleitung aus einem einzelnen Urinanstieg ableiten. Bei echter Exposition toxikologische Anamnese, validierte Proben und Nierenfunktion verwenden.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('01a80c8a-efb4-5052-8e02-c8d85577b416', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-footbath-metals', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Platin-Fußbad, 20-Personen-Studie und rechtliche Auseinandersetzung', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-footbath-metals', 'unknown', 'Folge 014 38:35-42:42 E014-015', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-footbath-metals","aliases":["Platin-Fußbad, 20-Personen-Studie und rechtliche Auseinandersetzung"],"tags":["Ausleitung","Erfahrungsheilkunde","Folge 014","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Ausleitung"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Nicht aufgrund braunen Wassers oder Prozentwerten eine Entgiftung annehmen. Elektrische Gerätesicherheit, Hautzustand, Implantate, Schwangerschaft, Arzneien und hygienische Aufbereitung prüfen; keine Krebs-, Neuro- oder Autismustherapie ersetzen.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E014-015; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt stellt ein ionisches Fußbad vor. Eine Ärztin, deren Name als ''Margarita Cris-Bresson'' unsicher erfasst ist, habe nach neurologischer Ausbildung in den USA und Arbeit in Lörrach beziehungsweise London auf seine frühere Skepsis reagiert und eine Studie an 20 Patienten durchgeführt. Sie habe nicht das Badewasser, sondern Urinaluminium nach verschiedenen Geräten gemessen und nur bei einem Fußbad mit Platinspule einen starken Anstieg gefunden. Danach sei ein mit KI/AI verfasster Artikel unter Übernahme seiner Vorlesung erschienen; er fordert harte Strafen, spricht über Anwälte und Schwierigkeiten, Verantwortliche zu finden, und betont, am Gerät nie verdient zu haben. Nicky kümmere sich um rechtliche Fragen. Acht Stunden nach einem 30-minütigen Platinspulen-Fußbad habe die Aluminiumausscheidung um 900 Prozent zugenommen; auch andere toxische Metalle, besonders Quecksilber, würden ausgeschieden.\n\n## Genannte Mittel oder Verfahren\n- Ionisches Fußbad mit behaupteter Platinspule und gepulsten Frequenzen\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nEinzelanwendung: 30 Minuten; Messzeitpunkt: acht Stunden danach; behauptete Zunahme: 900 %. Studiengruppe laut Sprecher: 20 Personen.\n\n## Sprecher und Fundstellen\n- Folge 014 · 38:35-42:42 · E014-015 · DK\n\n## Unabhängige Evidenzeinordnung\nDie vorgelegte 900-%-Studie war nicht auffindbar und kann ohne Protokoll, Rohdaten, Vergleichsgruppe und Publikation nicht bewertet werden. Eine veröffentlichte objektive Prüfung mit sechs Teilnehmenden und Kontrollen fand nach vier wöchentlichen 30-Minuten-Anwendungen keine induzierte Ausscheidung toxischer Elemente über Füße, Urin oder Haar; Metall im Wasser war überwiegend mit Elektrodenkorrosion vereinbar [S26].\n\n## Sicherheit · BEACHTEN\nNicht aufgrund braunen Wassers oder Prozentwerten eine Entgiftung annehmen. Elektrische Gerätesicherheit, Hautzustand, Implantate, Schwangerschaft, Arzneien und hygienische Aufbereitung prüfen; keine Krebs-, Neuro- oder Autismustherapie ersetzen.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('40061e4c-0355-50a5-a9e8-5dac86e6566a', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-footbath-autism', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Ionisches Fußbad bei behaupteter Aluminiumbelastung und Autismus', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-footbath-autism', 'unknown', 'Folge 014 42:42-46:30 E014-016; Folge 024 46:31-49:48 E024-020', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-footbath-autism","aliases":["Ionisches Fußbad bei behaupteter Aluminiumbelastung und Autismus"],"tags":["Ausleitung","Erfahrungsheilkunde","Folge 014","Folge 024","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Ausleitung"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Kinder nicht gegen Widerstand im Gerät halten und Bildschirm nicht als Zwangsmittel einsetzen. Verbrennung, Hautschaden, Strom- und Kontaminationsrisiken beachten. Evidenzbasierte Autismusunterstützung nicht verzögern.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E014-016, E024-020; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt behauptet, Koriander, Alu-Tops und Fußbad entfernten Aluminium. Eine unveröffentlichte Studie an autistischen Kindern, an der er beteiligt gewesen sei, habe mit einem als ''A-Tech'' erfassten, wahrscheinlich ATEC gemeinten Fragebogen nach vier Monaten eine 55-prozentige Verbesserung gezeigt. Autistische Erwachsene im Alter von 25 oder 30 Jahren hätten sogar stärker reagiert als Kinder. Das Protokoll sei viermal wöchentlich je 30 Minuten über vier Monate, danach meist zwei- bis dreimal pro Woche. Eltern müssten Kinder mit Computer oder anderem ablenken, damit sie im Bad blieben. Wirksam seien nur Geräte mit richtiger gepulster Frequenz und Platin; billige Internetgeräte mit Mischmetallspule färbten Wasser braun und könnten toxische Metalle über den Fuß aufnehmen. Aluminium sei Kern von Verkalkung und Alzheimer; die gegebene Methode entgifte es aus dem Gehirn. Deutschland sei in US-Militärkreisen als ''Chemtrail Heaven'' bekannt.\n\n## Genannte Mittel oder Verfahren\n- Platinspulen-Fußbad; Koriander; Alu-Tops; langfristiges Erhaltungsprotokoll\n- Platinspulen-Fussbad fuer autistische Kinder und Erwachsene\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\n30 Minuten, viermal pro Woche über vier Monate; danach laut Folge 014 meist zwei- bis dreimal pro Woche. Behauptete ATEC-Verbesserung 55 %.\n\n## Sprecher und Fundstellen\n- Folge 014 · 42:42-46:30 · E014-016 · DK\n- Folge 024 · 46:31-49:48 · E024-020 · DK\n\n## Unabhängige Evidenzeinordnung\nOhne publiziertes Protokoll, Randomisierung, Verblindung, Kontrollgruppe, Ausgangswerte und Rohdaten kann die 55-%-ATEC-Angabe keine Wirksamkeit belegen. ATEC ist ein betreuerberichtetes Verlaufsinstrument und kein Metallnachweis. Die unabhängige Fußbadprüfung war negativ [S26]. Aluminium ist keine notwendige oder hinreichende Ursache von Autismus oder Alzheimer [S14, S15].\n\n## Sicherheit · BEACHTEN\nKinder nicht gegen Widerstand im Gerät halten und Bildschirm nicht als Zwangsmittel einsetzen. Verbrennung, Hautschaden, Strom- und Kontaminationsrisiken beachten. Evidenzbasierte Autismusunterstützung nicht verzögern.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('ac87a0e5-448e-5c49-a20a-3a5408df53b3', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-eboo-frequency', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Bioflavonoid-Cocktail, Ozonfrequenzen und Filterverluste', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-eboo-frequency', 'unknown', 'Folge 022 35:02-38:12 E022-018', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-eboo-frequency","aliases":["Bioflavonoid-Cocktail, Ozonfrequenzen und Filterverluste"],"tags":["Erfahrungsheilkunde","Folge 022","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage","Therapieverfahren"],"therapeutic_topics":["Therapieverfahren"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Keine Frequenz aus Anekdoten übernehmen. Katheter, Antikoagulation, Ozon, Blutverlust, Hämolyse, Embolie, Infektion und unbekannte Filtereffekte machen Wiederholungsserien hochriskant.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E022-018; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nGegen die angebliche stationäre Lymeform nennt Klinghardt seinen an BioPure gegebenen Lyme-Cocktail, wahrscheinlich Cryptolepis, Monolaurin und weitere Bioflavonoide/Polyphenole; Antibiotika erreichten sie nur in tödlicher Dosis, Pflanzenstoffe drängen sanft in Zellen und blockierten die Erregermaschinerie. Für EBOO nennt er eine Kollegenempfehlung von viermal jährlich, akzeptiert vorübergehend wöchentlich und sieht im Ozonanteil sogar tägliche Anwendung als möglich. Er berichtet von drei täglichen 10-Pass-Ozonbehandlungen bei sich und 30-Pass-Anwendung bei Krebs. Der Filter entferne aber neben Zytokinen, Erregern und ''Schmutz'' wahrscheinlich Cortisol, Hormone und andere nötige Blutbestandteile; Schwerkranke brauchten vier bis fünf Wochen Erholung, weshalb er EBOO höchstens alle sechs Wochen, bei Lyme viermal jährlich, ansetzt.\n\n## Genannte Mittel oder Verfahren\n- Lyme-Cocktail/Bioflavonoide; EBOO; 10-Pass- und 30-Pass-Ozon\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nEBOO viermal/Jahr; kurzfristig wöchentlich; Limit etwa alle 6 Wochen; Ozon 3 Tage 10-Pass, bei Krebs 30-Pass; Kräuterdosen fehlen.\n\n## Sprecher und Fundstellen\n- Folge 022 · 35:02-38:12 · E022-018 · DK\n\n## Unabhängige Evidenzeinordnung\nEinzelne Extrakte zeigen nur in vitro Aktivität; Monolaurin war in der zitierten Studie wenig oder nicht aktiv [S20]. Für EBOO-/Mehrpassozon fehlen im Track kontrollierte Nutzen-, Dosis- und Filterselektivitätsdaten [S19].\n\n## Sicherheit · BEACHTEN\nKeine Frequenz aus Anekdoten übernehmen. Katheter, Antikoagulation, Ozon, Blutverlust, Hämolyse, Embolie, Infektion und unbekannte Filtereffekte machen Wiederholungsserien hochriskant.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('8b1e0d97-e996-5441-a437-f57e7ef520e1', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-ozone-lyme-viruses', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: IV-Ozon: Mikroperfusion, Stammzellclaim und nur vorübergehende Besserung', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-ozone-lyme-viruses', 'unknown', 'Folge 022 55:00-58:43 E022-026', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-ozone-lyme-viruses","aliases":["IV-Ozon: Mikroperfusion, Stammzellclaim und nur vorübergehende Besserung"],"tags":["Erfahrungsheilkunde","Folge 022","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage","Therapieverfahren"],"therapeutic_topics":["Therapieverfahren"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Keine IV-/Ozoninjektion oder extrakorporale Ozonierung zur Selbst- oder Ersatztherapie. Gasembolie, Hämolyse, Gefäßzugang, Infektion und oxidativer Schaden beachten.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E022-026; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nAuf eine weitere Ozonfrage sagt Klinghardt, IV-Ozon töte nicht nur Erreger, sondern erhöhe Mikrozirkulation und Durchblutung von Gehirn, Nieren, Knochen und Genitalien und rege Knochen stark zur Stammzellfreisetzung an. Österreichische 10- und 30-Pass-Verfahren sowie US-Kollegen werden gelobt; regelmäßige Injektionen hätten EBV, HHV-6, Coxsackie und andere Viren besiegt. Zugleich sagt er, bei chronischer Lyme seien radikale oder dauerhafte Erfolge nicht gesehen worden: Besserung halte eine bis sechs Wochen, höchstens ungefähr drei Monate; EBOO könne etwa drei Monate wirken. Individuelle Ärzte hätten zu wenig Erfahrung für belastbare Häufigkeitsangaben.\n\n## Genannte Mittel oder Verfahren\n- IV-Ozon, Mehrpassozon und EBOO gegen Lyme/Viren\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\n10- oder 30-Pass; Wirkung behauptet 1-6 Wochen, maximal etwa 3 Monate; keine Ozonkonzentration.\n\n## Sprecher und Fundstellen\n- Folge 022 · 55:00-58:43 · E022-026 · DK\n\n## Unabhängige Evidenzeinordnung\nDer Track präsentiert keine kontrollierten Daten zu Eradikation, Stammzellfreisetzung oder klinischem Nutzen. Ozon ist toxisch und nicht als generelle Infektionsbehandlung anerkannt [S19].\n\n## Sicherheit · BEACHTEN\nKeine IV-/Ozoninjektion oder extrakorporale Ozonierung zur Selbst- oder Ersatztherapie. Gasembolie, Hämolyse, Gefäßzugang, Infektion und oxidativer Schaden beachten.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('3a8abc72-d8cd-57c5-92bb-11b9d0f2113e', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-head-compression', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Fluorid in der Luft, Chemtrailvorbehalt und tägliche Kopfkompression', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-head-compression', 'unknown', 'Folge 022 20:22-21:42 E022-011', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-head-compression","aliases":["Fluorid in der Luft, Chemtrailvorbehalt und tägliche Kopfkompression"],"tags":["Erfahrungsheilkunde","Folge 022","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage","Therapieverfahren"],"therapeutic_topics":["Therapieverfahren"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Keine kräftige Kopf-/Halskompression. Bei Gefäßerkrankung, Trauma, Blutverdünnung, Schwindel oder neurologischen Symptomen mechanische Eigenbehandlung vermeiden und fachlich abklären.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E022-011; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt sagt, die vermutete Fluoridbelastung aus der Luft berühre die Chemtrailfrage; sie sei möglich, aber von ihm nicht untersucht, und ein im Track unklarer Experte habe Fluorid nicht erwähnt. Als weitere Epiphysenentgiftung nennt er Sakralarbeit und seine Kopfkompression: einmal täglich eine Minute solle sie die tiefen Halsvenen im Sinne der CCSVI-Erzählung öffnen, Gehirn und Epiphyse massiv besser durchbluten und Toxine ausspülen.\n\n## Genannte Mittel oder Verfahren\n- Sakralarbeit; manuelle Kopfkompression zur Öffnung tiefer Halsvenen\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nEinmal täglich eine Minute; keine Kraft, Handposition oder Kontraindikation.\n\n## Sprecher und Fundstellen\n- Folge 022 · 20:22-21:42 · E022-011 · DK\n\n## Unabhängige Evidenzeinordnung\nDie Folge liefert keine Luftmessung für Fluorid. Eine sham-kontrollierte Studie stützte CCSVI-Venoplastie bei MS nicht [S11]; daraus folgt erst recht kein Nachweis, dass Kopfkompression Venen öffnet oder Gehirntoxine entfernt.\n\n## Sicherheit · BEACHTEN\nKeine kräftige Kopf-/Halskompression. Bei Gefäßerkrankung, Trauma, Blutverdünnung, Schwindel oder neurologischen Symptomen mechanische Eigenbehandlung vermeiden und fachlich abklären.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('fb06ef89-f95e-5ad2-83da-47ffe610f9de', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-intranasal-infrared', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Laserakupunktur, transkranielles/intranasales Infrarot und Feldruecktransport', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-intranasal-infrared', 'unknown', 'Folge 023 42:12-45:22 E023-021', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-intranasal-infrared","aliases":["Laserakupunktur, transkranielles/intranasales Infrarot und Feldruecktransport"],"tags":["Erfahrungsheilkunde","Folge 023","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage","Therapieverfahren"],"therapeutic_topics":["Therapieverfahren"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Keine intranasale oder transkranielle Selbstbehandlung mit unbekanntem Laser. Augen, Schleimhaut, Waerme, Epilepsie, Implantate und Arzneitherapie beachten; Parkinsonversorgung nicht ersetzen.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E023-021; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt nennt Dinshah-Buehnenlicht, deutsche Laserakupunktur, transkranielles Infrarot durch die Schaedeldecke bei Parkinson und chronischer Muedigkeit sowie billige intranasale Geraete mit zwei Lampen. In etwa 20 Minuten fliesse das gesamte Blut an den Nasenlampen vorbei und werde mit Rot- oder bevorzugt Infrarotlicht angereichert. Gegen Wissenschaftler, die direkte Bestrahlung fordern, setzt er sein Feldmodell: Koerperphotonen trugen alle Informationen nach aussen; Begegnungen auf dem Lichtweg wuerden auf demselben Strahl in Ursprungszellen zurueckgetragen. Ein Artikel von 2015 bestaetige Neuroprotektion durch Licht aus der Ferne.\n\n## Genannte Mittel oder Verfahren\n- Laserakupunktur; transkranielle und intranasale Rot-/NIR-Anwendung; indirekte Feldbestrahlung\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nIntranasal etwa 20 Minuten; transkranielle und sonstige Wellenlaengen/Leistungen fehlen. Sprecher bevorzugt Infrarot gegenueber Rot.\n\n## Sprecher und Fundstellen\n- Folge 023 · 42:12-45:22 · E023-021 · DK\n\n## Unabhängige Evidenzeinordnung\nTranskranielle PBM wird mit parameterabhaengigen praeklinischen und begrenzten klinischen Daten erforscht; Gewebepenetration und Dosis variieren stark [S17]. Das bestaetigt weder Parkinsonheilung, ''gesamtes Blut'' als Ziel noch zellgenauen Ruecktransport beliebiger Informationen. Laserprodukte haben strahlungsspezifische Risiken [S23].\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Keine intranasale oder transkranielle Selbstbehandlung mit unbekanntem Laser. Augen, Schleimhaut, Waerme, Epilepsie, Implantate und Arzneitherapie beachten; Parkinsonversorgung nicht ersetzen.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('d229c552-0814-5dcd-bf2d-34a63ae8c8a3', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-photonwave-neurotransmitters', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Photo-Neuro-Immunologie und unveroeffentlichte Liquor-Farbversuche', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-photonwave-neurotransmitters', 'unknown', 'Folge 023 50:47-53:58 E023-024', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-photonwave-neurotransmitters","aliases":["Photo-Neuro-Immunologie und unveroeffentlichte Liquor-Farbversuche"],"tags":["Erfahrungsheilkunde","Folge 023","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage","Therapieverfahren"],"therapeutic_topics":["Therapieverfahren"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Keine Lumbalpunktion zur Geraete-/Farbwahl. Lumbalpunktion braucht klare medizinische Indikation, sterile Technik und Komplikationsaufklaerung; ART nicht zur Neurotransmitterdiagnostik verwenden.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E023-024; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt sagt, sichtbares Augenlicht veraendere seit etwa 1995 bekannt Immunantwort, Hormone und Neuropeptide. Er nennt unter anderem Noradrenalin, Acetylcholin, VIP und Gastrin-Releasing-Peptide, kennt aber keine Arbeit, die benoetigte Spektralbereiche festlegt; deshalb muesse ART individuell waehlen. Mit einem als Norm Schiele gehoerten Kollegen habe er bei Patienten Lumbalpunktionen durchgefuehrt, die Nadel liegen gelassen, zwanzig Minuten mit einer Farbe/Frequenz, beispielhaft Blau mit Frequenz 7, bestrahlt und dramatische, aber unvorhersehbare Neurotransmitteraenderungen gefunden. Daraus sei die moderne PhotonWave-Therapie entstanden, weiterentwickelt von Leona und Katja.\n\n## Genannte Mittel oder Verfahren\n- Okulare PhotonWave-Farbe/Frequenz mit Liquormessung und ART-Auswahl\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nBeispiel Blau, Frequenz 7, 20 Minuten; Fallzahl, Einheit, Lichtleistung, Liquorparameter und Kontrollen fehlen.\n\n## Sprecher und Fundstellen\n- Folge 023 · 50:47-53:58 · E023-024 · DK\n\n## Unabhängige Evidenzeinordnung\nIntrinsisch photosensitive retinale Ganglienzellen vermitteln nicht bildgebende Lichtsignale [S18]. Das validiert weder universelle Peptidsteuerung noch ART als individuelle Spektralanalyse [S04]. Ohne Protokoll, Ethik, Kontrollen, Messverfahren und Rohdaten ist die invasive Vorher-nachher-Erzaehlung nicht auswertbar.\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Keine Lumbalpunktion zur Geraete-/Farbwahl. Lumbalpunktion braucht klare medizinische Indikation, sterile Technik und Komplikationsaufklaerung; ART nicht zur Neurotransmitterdiagnostik verwenden.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('11363f9e-6e7a-5c2a-94fc-4cb8000f4dea', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-bright-light-depression', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Helllicht-Fluoxetin-RCT bei nicht saisonaler Depression', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-bright-light-depression', 'unknown', 'Folge 021 17:45-21:29 E021-011', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-bright-light-depression","aliases":["Helllicht-Fluoxetin-RCT bei nicht saisonaler Depression"],"tags":["Erfahrungsheilkunde","Erkrankungen und Symptome","Folge 021","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Erkrankungen und Symptome"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Antidepressiva nicht abrupt absetzen. Helllicht bei bipolarer Störung, Augenkrankheit, kürzlicher Augenoperation oder photosensibilisierenden Arzneien fachlich prüfen; bei Suizidalität akut Hilfe suchen [S04].","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E021-011; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt bespricht eine JAMA-Psychiatry-Studie mit 122 Patienten. Er sagt zutreffend, Fluoxetin allein habe Placebo nicht signifikant übertroffen und Helllicht allein sei signifikant besser gewesen, verspottet aber Antidepressiva als teure nicht wirkende Mittel und unterstellt, die Autoren hätten aus Publikationszwang trotzdem die Kombination empfohlen. Als praktische Anwendung nennt er 10.000 Lux weißes Licht für 30 Minuten früh morgens und schlägt Lampen rechts und links vom Computer vor.\n\n## Genannte Mittel oder Verfahren\n- Helllichtbox; Fluoxetin; Kombinationstherapie\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nIm Vortrag: 10.000 Lux weißes Licht für 30 Minuten früh morgens. Eine Fluoxetindosis wird im Vortrag nicht sicher genannt.\n\n## Sprecher und Fundstellen\n- Folge 021 · 17:45-21:29 · E021-011 · DK\n\n## Unabhängige Evidenzeinordnung\nIm achtwöchigen RCT waren Helllicht allein und Kombination signifikant besser als Placebo, Fluoxetin allein nicht; die Kombination zeigte die konsistentesten Effekte [S03]. Das Ergebnis dieses einzelnen RCT beweist weder generelle Unwirksamkeit von Antidepressiva noch, dass Fluoxetin nur durch Licht wirke.\n\n## Sicherheit · BEACHTEN\nAntidepressiva nicht abrupt absetzen. Helllicht bei bipolarer Störung, Augenkrankheit, kürzlicher Augenoperation oder photosensibilisierenden Arzneien fachlich prüfen; bei Suizidalität akut Hilfe suchen [S04].\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('522676be-e3d2-5699-aef9-00515821745d', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-photonwave-hallucinations', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Halluzinationsfall, vermutete Metallbelastung und Lichtweg mit DMPS/EDTA', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-photonwave-hallucinations', 'unknown', 'Folge 021 43:17-45:31 E021-025', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-photonwave-hallucinations","aliases":["Halluzinationsfall, vermutete Metallbelastung und Lichtweg mit DMPS/EDTA"],"tags":["Erfahrungsheilkunde","Folge 021","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage","Therapieverfahren"],"therapeutic_topics":["Therapieverfahren"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Halluzinationen und Verwirrtheit zeitnah medizinisch/psychiatrisch abklären; bei Gefährdung Notfallhilfe. Chelatoren weder real noch als angebliche Lichtinformation ohne bestätigte Vergiftung einsetzen.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E021-025; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt erzählt von einer mittellosen Krankenschwester, die täglich Halluzinationen und nur kurze klare Phasen gehabt habe. Seine ART-Diagnose habe eine im ASR nicht sicher bestimmbare Metallvergiftung, wahrscheinlich Cadmium, ergeben. Weil reguläre Entgiftung zu teuer gewesen sei, habe man etwa sechs Sitzungen gemacht und DMPS sowie ein als EDTA oder ähnlich gehörtes Mittel nur auf den Lichtweg gestellt. Zwischen zwei im Track widersprüchlich datierten Messungen über ungefähr fünf Monate seien Metallwerte gefallen und die Halluzinationen vollständig verschwunden; weitere Behandlungen habe sie nicht erhalten.\n\n## Genannte Mittel oder Verfahren\n- PhotonWave mit DMPS und wahrscheinlich EDTA als Lichtvorlagen; ART-Metalldiagnose\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nUngefähr 6 Sitzungen; Beobachtungszeit etwa 5 Monate; keine tatsächliche Arzneidosis.\n\n## Sprecher und Fundstellen\n- Folge 021 · 43:17-45:31 · E021-025 · DK\n\n## Unabhängige Evidenzeinordnung\nEin Vorher-nachher-Fall ohne bestätigte Diagnose, Verlaufskontrolle, Verblindung oder Vergleich beweist keine Kausalität. Halluzinationen haben zahlreiche psychiatrische, neurologische, medikamentöse und toxische Ursachen [S21]. ART ist kein Metalltest [S12], provozierte Urinwerte sind problematisch [S16].\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Halluzinationen und Verwirrtheit zeitnah medizinisch/psychiatrisch abklären; bei Gefährdung Notfallhilfe. Chelatoren weder real noch als angebliche Lichtinformation ohne bestätigte Vergiftung einsetzen.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('e931bef1-138e-5b6d-b608-bd55a9fc2f6a', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-orange-light-crohn', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Farbtherapiegeschichte und angebliche Crohn-Heilung durch Orangenlicht', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-orange-light-crohn', 'unknown', 'Folge 023 02:34-04:03 E023-003', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-orange-light-crohn","aliases":["Farbtherapiegeschichte und angebliche Crohn-Heilung durch Orangenlicht"],"tags":["Erfahrungsheilkunde","Erkrankungen und Symptome","Folge 023","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Erkrankungen und Symptome"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Crohn-Medikamente, Endoskopie und Komplikationskontrolle nicht durch Farblicht ersetzen. Starke Bauchschmerzen, Fieber, Blutung, Erbrechen oder Obstruktionszeichen akut abklaeren.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E023-003; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt ordnet diagnostische und therapeutische Lichtarbeit historisch ein: Rudolf Steiner habe Krankenhauszimmer mit Farbfiltern entwickelt; in Indien habe er Edelsteine, farbige Glaeser, Kerzen und Filter kennengelernt. Eine junge Patientin mit laut Auto-Track ''Mobius Crohn'', kontextuell Morbus Crohn, sei unter seinen Augen geheilt worden, nachdem ihr Bauch taeglich eine Stunde mit Orangenlicht bestrahlt worden sei. Nach einer Woche oder zehn Tagen habe Besserung begonnen, nach ungefaehr vier Wochen sei sie geheilt gewesen.\n\n## Genannte Mittel oder Verfahren\n- Orangenlicht auf den Bauch bei behauptetem Morbus Crohn\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nEine Stunde taeglich; Besserungsbeginn nach 7-10 Tagen; behauptete Heilung nach etwa 4 Wochen. Wellenlaenge, Intensitaet und Begleittherapie fehlen.\n\n## Sprecher und Fundstellen\n- Folge 023 · 02:34-04:03 · E023-003 · DK\n\n## Unabhängige Evidenzeinordnung\nMorbus Crohn ist eine chronisch-entzuendliche Darmerkrankung. NIDDK beschreibt Medikamente, Ernaehrungs-/Komplikationsmanagement und gegebenenfalls Operation, aber keine kurative abdominale Orangenbestrahlung [S02]. Ein unkontrollierter Verlauf kann Remission, Begleittherapie oder Fehldiagnose nicht trennen.\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Crohn-Medikamente, Endoskopie und Komplikationskontrolle nicht durch Farblicht ersetzen. Starke Bauchschmerzen, Fieber, Blutung, Erbrechen oder Obstruktionszeichen akut abklaeren.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('20bfbe1c-7b22-569d-8a1f-22464215f857', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-blue-light-ms', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Acht Jahre Rollstuhl und angebliches Gehen nach blauem gepulstem Licht', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-blue-light-ms', 'unknown', 'Folge 025 29:03-31:29 E025-014', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-blue-light-ms","aliases":["Acht Jahre Rollstuhl und angebliches Gehen nach blauem gepulstem Licht"],"tags":["Erfahrungsheilkunde","Erkrankungen und Symptome","Folge 025","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Erkrankungen und Symptome"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: MS-Therapie nicht absetzen oder durch Licht ersetzen. Neue Geh-, Blasen-, Seh- oder Lähmungsstoerungen akut neurologisch abklaeren.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E025-014; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nEine bekannte Hollywood-Psychologin sei wegen schwerer multipler Sklerose acht Jahre im Rollstuhl gewesen. Klinghardt habe sie 1986 per ART auf Blau mit Frequenz sieben oder acht getestet und vor ein Lichtgeraet gesetzt. Nach etwa 15 Minuten sei sie wegen Harndrangs aufgestanden, acht oder neun Raeume zur Toilette gelaufen und habe erst danach bemerkt, erstmals seit acht Jahren wieder zu gehen. Dies sei sein Einstieg in die Lichttherapie gewesen; spaeter habe es Konflikte mit der Aerztekammer gegeben.\n\n## Genannte Mittel oder Verfahren\n- Blaues gepulstes Licht nach ART-Auswahl bei multipler Sklerose\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nEtwa 15 Minuten; Blau; Frequenz 7 oder 8, vom Sprecher vergessen. Leistung, Pulsbreite, Wellenlaenge und Begleittherapie fehlen.\n\n## Sprecher und Fundstellen\n- Folge 025 · 29:03-31:29 · E025-014 · DK\n\n## Unabhängige Evidenzeinordnung\nMS kann fluktuierende Symptome verursachen und benoetigt neurologische Diagnose sowie krankheitsmodifizierende/symptomatische Behandlung [S11]. Eine einzelne Erinnerung ohne Befunde, Diagnoseverifikation, Kontrolle und Nachbeobachtung belegt keine Wiederherstellung der Gehfaehigkeit durch blaues Licht. PBM-Evidenz ist parameter- und indikationsspezifisch [S07].\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: MS-Therapie nicht absetzen oder durch Licht ersetzen. Neue Geh-, Blasen-, Seh- oder Lähmungsstoerungen akut neurologisch abklaeren.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('5f01620e-6589-5c38-b7b2-fdff07684c38', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-emf-protection', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Schutzkleidung, Stetzer-Filter, Body Voltage und Rollstuhl-Anekdote', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-emf-protection', 'unknown', 'Folge 014 55:11-57:49 E014-020', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-emf-protection","aliases":["Schutzkleidung, Stetzer-Filter, Body Voltage und Rollstuhl-Anekdote"],"tags":["Erfahrungsheilkunde","Folge 014","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage","Therapieverfahren"],"therapeutic_topics":["Therapieverfahren"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Filter nicht als Behandlung von Lähmung, Rollstuhlbedarf oder neurologischen Erkrankungen verwenden. Nur normgerechte Geräte einsetzen; Steckdosen und Leitungen nicht selbst verändern.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E014-020; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt trägt tagsüber Schutzkleidung und nachts beziehungsweise im Flugzeug eine Schutzmütze. Kritiker bezeichnet er als Pseudowissenschaftler; bei 600 oder 800 eigenen Patienten gehe es mit Kleidung sofort und maximal besser. Stetzer-Filter habe er in Deutschland eingeführt; sie sollten ''schmutzige'' gepulste Felder aus Steckdosen, Leitungen, Fernsehern und Lampen säubern, die auch bei ausgeschaltetem Licht bestünden. ''Body Voltage'' sei der Messwert und an vielen Schlafplätzen katastrophal. Videos zeigten angeblich, wie ein Rollstuhlnutzer zwei Minuten nach Einstecken eines Filters entspanne, aufstehe und gehe. Graham Stetzer, als Physiker in San Diego beschrieben, habe ein zuverlässiges Messgerät auf Grundlage echter Physik entwickelt.\n\n## Genannte Mittel oder Verfahren\n- EMF-Schutzkleidung/-mütze; Stetzer-Filter; Body-Voltage-/GS-Messung\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nKleidung tagsüber, Mütze nachts und beim Fliegen; Filterwirkung angeblich innerhalb von zwei Minuten. Keine Tragepause, Feldstärke oder Anzahl Filter.\n\n## Sprecher und Fundstellen\n- Folge 014 · 55:11-57:49 · E014-020 · DK\n\n## Unabhängige Evidenzeinordnung\nEin systematischer Review fand unterschiedliche Messmethoden, keinen belegten 50-GS-Sicherheitsgrenzwert und überwiegend Fallberichte, unverblindete Selbstberichte und ökologische Daten; die Evidenz für gesundheitliche Wirkungen hochfrequenter Spannungstransienten bestand wissenschaftlicher Prüfung nicht [S33]. Unkontrollierte Vorher-nachher-Videos und eine Behandlerserie beweisen keine Gehfähigkeit oder neurologische Wirkung.\n\n## Sicherheit · BEACHTEN\nFilter nicht als Behandlung von Lähmung, Rollstuhlbedarf oder neurologischen Erkrankungen verwenden. Nur normgerechte Geräte einsetzen; Steckdosen und Leitungen nicht selbst verändern.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('50905225-ef0c-509c-9442-09c03f6148b0', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-brain-training', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Gezieltes Gehirntraining, Bewegung, Plasmalogenöle und drei Monate Reserve', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-brain-training', 'unknown', 'Folge 015 40:57-43:27 E015-019', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-brain-training","aliases":["Gezieltes Gehirntraining, Bewegung, Plasmalogenöle und drei Monate Reserve"],"tags":["Erfahrungsheilkunde","Folge 015","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DM","Sprecheraussage","Therapieverfahren"],"therapeutic_topics":["Therapieverfahren"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Nahrungsergänzungen auf Inhaltsstoffe, Allergene, Qualität und Interaktionen prüfen [S30]. Bei Funktionsverlust Training an Sturz-, Überlastungs- und Verkehrssicherheit anpassen und reguläre Diagnostik nicht verzögern.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E015-019; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nNeben Schlaf sei entscheidend, genau die beeinträchtigten Hirnareale regelmäßig herauszufordern; Kreuzworträtsel passten nicht für alle. Bei gleicher Neuronenzahl entwickle eine Person mit passendem Gehirntraining und Bewegung über ''brain drive nerve growth factor'' mehr synaptische Netzwerke. Musnick entwerfe deshalb regionsspezifische Übungen. Zusätzlich verwende er als ''plasma balancing oils'' erfasste, wahrscheinlich Plasmalogenprodukte: ''ProdromeGlia'' solle überaktive dysfunktionale Gliazellen modulieren; ein zweites Produkt sei wahrscheinlich das damals als ProdromeNeuro bezeichnete Mittel und werde mit Phosphatidylcholin kombiniert, um Neuronen zu verbessern. Nahrungsergänzungen, sein Gehirntraining und das gesamte Programm sollten mindestens drei Monate über vollständige Beschwerdefreiheit hinaus fortgesetzt werden, um maximale Reserve statt einer knappen Symptomschwelle zu erreichen.\n\n## Genannte Mittel oder Verfahren\n- Regionsspezifische kognitive Aufgaben; Bewegung; ProdromeGlia; wahrscheinlich ProdromeNeuro; Phosphatidylcholin; Gesamtprogramm\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nÜbungen regelmäßig; Supplement-/Trainingsprogramm mindestens 3 Monate über subjektive Beschwerdefreiheit hinaus. Keine Produktdosis.\n\n## Sprecher und Fundstellen\n- Folge 015 · 40:57-43:27 · E015-019 · DM\n\n## Unabhängige Evidenzeinordnung\nBewegung und bestimmte Formen kognitiven Trainings können einzelne kognitive Ziele unterstützen, doch dauerhafte Effekte und Übertragbarkeit sind nicht für alle Aktivitäten definitiv [S24]. Eine kleine RCT eines anderen Plasmalogen-Elastin-Präparats zeigte einzelne Gedächtnisendpunkte bei gesunden Älteren [S25]; das beweist weder ProdromeGlia/Neuro, Gliazell-''Modulation'', Demenzumkehr noch die genannte Dreimonatsregel. NIA empfiehlt derzeit kein Vitamin oder Supplement zur Prävention von Alzheimer oder allgemeinem kognitivem Abbau [S24].\n\n## Sicherheit · BEACHTEN\nNahrungsergänzungen auf Inhaltsstoffe, Allergene, Qualität und Interaktionen prüfen [S30]. Bei Funktionsverlust Training an Sturz-, Überlastungs- und Verkehrssicherheit anpassen und reguläre Diagnostik nicht verzögern.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('b3962848-e0f9-5c6b-a238-7f688b56fc8b', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-car-scan-autism', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Neun-Personen-Autismusstudie mit teleportiertem Methylfolat', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-car-scan-autism', 'unknown', 'Folge 023 35:00-37:51 E023-017', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-car-scan-autism","aliases":["Neun-Personen-Autismusstudie mit teleportiertem Methylfolat"],"tags":["Erfahrungsheilkunde","Folge 023","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage","Therapieverfahren"],"therapeutic_topics":["Therapieverfahren"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Folatmangel labor- und ursachenbezogen behandeln; keine notwendige Supplementation durch Licht ersetzen. Autistische Menschen nicht als ''schwer krank'' pauschalisieren und objektive, einwilligungsbasierte Endpunkte verlangen.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E023-017; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt beschreibt eine kleine eigene Studie mit neun schwer kranken autistischen Personen im Alter von 18 bis 62 Jahren. Ueber sechs Monate seien sie beobachtet und in den ersten etwa drei Monaten sechsmal, spaeter als durchschnittlich 6,4 Behandlungen bezeichnet, mit dem CAR Scan behandelt worden. Als einzig gegebenes Mittel nennt er ein im Track als Chlorella-Spindelmittel gehoertes Praeparat; fluessige Methylfolsaeure habe nur im Signalverstaerker gestanden. Ein als genetisch unveraenderbar bezeichneter Tetrahydrofolatspiegel sei nach drei Monaten gestiegen und nach sechs Monaten naeher am Normwert gewesen. Er schliesst daraus auf reale Teleportation, da Diaet und Chlorella allein angeblich nichts geaendert haetten.\n\n## Genannte Mittel oder Verfahren\n- CAR Scan mit fluessiger Methylfolsaeure im Signalverstaerker; Chlorella als tatsaechlich gegebenes Mittel\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\n9 Personen, 18-62 Jahre; Beobachtung 6 Monate; 6 beziehungsweise durchschnittlich 6,4 Behandlungen, vorwiegend in 3 Monaten. Licht- und Chlorelladosis fehlen.\n\n## Sprecher und Fundstellen\n- Folge 023 · 35:00-37:51 · E023-017 · DK\n\n## Unabhängige Evidenzeinordnung\nFolatwerte koennen durch Ernaehrung, Absorption, Erkrankung, Medikamente, Laborvariation und tatsaechliche Supplemente beeinflusst werden [S15]. Neun unkontrollierte Personen, unklare Zielanalyse, widerspruechliche Sitzungszahl und Begleitmittel belegen keine materielose Methylfolatdosis oder Autismusbehandlung [S10, S11].\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Folatmangel labor- und ursachenbezogen behandeln; keine notwendige Supplementation durch Licht ersetzen. Autistische Menschen nicht als ''schwer krank'' pauschalisieren und objektive, einwilligungsbasierte Endpunkte verlangen.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('2e8cf94a-8081-519b-818a-f5ddd304381d', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-cyprus-brain-stimulation', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Gedächtnisangst und teure personalisierte Hirnstimulation auf Zypern', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-cyprus-brain-stimulation', 'unknown', 'Folge 022 51:39-55:00 E022-025', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-cyprus-brain-stimulation","aliases":["Gedächtnisangst und teure personalisierte Hirnstimulation auf Zypern"],"tags":["Erfahrungsheilkunde","Folge 022","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage","Therapieverfahren"],"therapeutic_topics":["Therapieverfahren"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Keine teure Reise oder Heimstimulation allein aus Testimonials. Anfallsrisiko, Implantate, Medikamente, Diagnose und Gerätesicherheit neurologisch prüfen.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E022-025; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt warnt zunächst davor, jede leichte Gedächtnisstörung sofort als Alzheimer zu vermarkten. Dann empfiehlt er eine im Auto-Track nicht identifizierbare Gruppe griechischer Wissenschaftler auf Zypern, die hochauflösende EEGs oder Scans mit elektrischer, mechanischer und magnetischer Hirnstimulation kombiniere. Dies sei die einzige ihn beeindruckende Parkinsonbehandlung: Mehrere Patienten seien hinein- und eine Woche später ohne Parkinson hinausgegangen. Der zweiwöchige Aufenthalt koste ungefähr 23.000 US-Dollar, ein individuell programmiertes Heimgerät rund 1.000 Dollar. Dauerhaftigkeit kenne er nicht und eine Beteiligung verneint er; zuerst wolle er Erreger behandeln und das Gehirn entgiften.\n\n## Genannte Mittel oder Verfahren\n- Personalisierte elektrische, mechanische und magnetische Hirnstimulation nach EEG/Scan\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Menge, Anwendung, Häufigkeit oder Dauer ist im Video genannt; fachlich bleibt sie ungeprüft.\n\nEtwa 2 Wochen; circa 23.000 USD plus ungefähr 1.000 USD für Heimgerät; Geräteeinstellungen fehlen.\n\n## Sprecher und Fundstellen\n- Folge 022 · 51:39-55:00 · E022-025 · DK\n\n## Unabhängige Evidenzeinordnung\nParkinson ist progredient; Medikamente, Reha und ausgewählte tiefe Hirnstimulation können Symptome bessern, heilen die Erkrankung aber nicht [S28]. Ohne Produktidentität, Zulassung, Endpunkte und Nachbeobachtung ist die Ein-Wochen-Heilung nicht bewertbar [S34].\n\n## Sicherheit · HOCH\nKeine teure Reise oder Heimstimulation allein aus Testimonials. Anfallsrisiko, Implantate, Medikamente, Diagnose und Gerätesicherheit neurologisch prüfen.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('61b00493-87a6-5490-83f7-333076c7083f', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-livessence-preparation', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Livessence, Eliminationswege und Die-off-Narrativ', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-livessence-preparation', 'unknown', 'Folge 007 32:45-35:17 E007-013', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-livessence-preparation","aliases":["Livessence, Eliminationswege und Die-off-Narrativ"],"tags":["Erfahrungsheilkunde","Folge 007","Interne Prüfung","Klinghardt-Talks","Pflanzenheilkunde","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Michele Milligan (Einzelzuordnung nicht strukturell kodiert)","Sprecheraussage"],"therapeutic_topics":["Pflanzenheilkunde"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Allergie, Hepatotoxizitaet, Interaktion, Infektionsprogress, Sepsis oder andere Ursachen nicht als Die-off abtun. Aktivkohle kann Arzneimittel binden und Aspiration/GI-Komplikationen verursachen.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E007-013; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nLivessence, Lymphatic Detox und Binder oeffneten Leber, Galle, Darm und weitere Eliminationswege. Unvertraeglichkeit des Cocktails sei meist Leber-/Darmstau; etwa sieben Tage Vorbehandlung koennten Reaktionen verhindern.\n\n## Genannte Mittel oder Verfahren\n- Livessence, Lymphatic Detox, Binder und Ernaehrungsanpassung.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nIm Video: möglicherweise 5, meist 7 Tage Vorbereitung. Eine Produktmenge wird im Video nicht eindeutig genannt.\n\n## Sprecher und Fundstellen\n- Folge 007 · 32:45-35:17 · E007-013 · Dr. Dietrich Klinghardt; Michele Milligan (Einzelzuordnung nicht strukturell kodiert)\n\n## Unabhängige Evidenzeinordnung\nEine Jarisch-Herxheimer-Reaktion ist eine akute, zeitlich begrenzte Entzuendungsreaktion nach Behandlung bestimmter Spirochaeteninfektionen. Es gibt keinen Beleg, dass Binder oder Leber-/Lymphtinkturen sie verhindern oder dass laengere Verschlechterung Entgiftung darstellt.\n\n## Sicherheit · BEACHTEN\nAllergie, Hepatotoxizitaet, Interaktion, Infektionsprogress, Sepsis oder andere Ursachen nicht als Die-off abtun. Aktivkohle kann Arzneimittel binden und Aspiration/GI-Komplikationen verursachen.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('b74649b0-0a39-5dfe-8992-d4a8f3934a51', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-silica-water-deferoxamine', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Siliziumreiches Wasser und Deferoxamin als Aluminiumchelator', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-silica-water-deferoxamine', 'unknown', 'Folge 014 37:23-38:35 E014-014', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-silica-water-deferoxamine","aliases":["Siliziumreiches Wasser und Deferoxamin als Aluminiumchelator"],"tags":["Ausleitung","Erfahrungsheilkunde","Folge 014","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Ausleitung"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. SAFETY_HOLD: Deferoxamin niemals selbst spritzen. Es erfordert klare Indikation, Dosierung und Nieren-, Augen-, Hör- und Infektionsmonitoring; Risiken umfassen Anaphylaxie, Neuro-/Ototoxizität, schwere Infektionen und bei falscher IV-Anwendung ARDS [S27].","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E014-014; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt kombiniert Koriander, Alu-Tops, Fußbad, Zeolith, Chlorella und silizium-/kieselsäurereiches Wasser. Eine in den USA verfügbare Quelle wird im Track unklar als ''neue Otto-Quelle'' und zugleich mit Berlin verbunden. Chris Exley habe regelmäßiges Trinken solchen Wassers als beste langfristige Aluminiumausleitung gefunden. Medizinisch verwende man Desferal/Deferoxamin, das Aluminium binde und ausscheide, die Blut-Hirn-Schranke aber nur wenig passiere. Seit COVID sei es in den USA und Kanada plötzlich nicht mehr erhältlich, weil es strategisch mit COVID-Ausleitungsmitteln wirke; COVID habe Aluminium für seine Tödlichkeit gebraucht und eine früh verwendete Injektion sei nach Bekanntwerden landesweit verschwunden.\n\n## Genannte Mittel oder Verfahren\n- Siliziumreiches Wasser; Deferoxamin/Desferal per Injektion; Kombination mit Pflanzen und Bindern\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nIm Video werden weder Wassermenge noch Deferoxamin-Dosis, Indikation oder Dauer genannt.\n\n## Sprecher und Fundstellen\n- Folge 014 · 37:23-38:35 · E014-014 · DK\n\n## Unabhängige Evidenzeinordnung\nEine kleine kontrollierte Studie berichtete unter bis zu 1 L siliziumreichem Wasser pro Tag mehr Aluminium im Urin und kognitive Verbesserung bei 3 von 15 Alzheimer-Teilnehmenden; sie war ausdrücklich vorläufig [S24]. Deferoxamin ist für Eisenüberladung zugelassen und wird bei dokumentierter Aluminiumtoxizität, vor allem im CKD-/Dialysekontext, off label fachärztlich eingesetzt [S27]. Dies belegt keine COVID-''Ausleitung'', politische Verknappung oder pauschale Anwendung.\n\n## Sicherheit · HOCH\nSAFETY_HOLD: Deferoxamin niemals selbst spritzen. Es erfordert klare Indikation, Dosierung und Nieren-, Augen-, Hör- und Infektionsmonitoring; Risiken umfassen Anaphylaxie, Neuro-/Ototoxizität, schwere Infektionen und bei falscher IV-Anwendung ARDS [S27].\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('7a8db4fe-18a7-53fd-8bfa-627cee7b4e3e', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-queen-springs-water', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Queen-Springs-Wasser und Mikroplastikabwägung', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-queen-springs-water', 'unknown', 'Folge 024 40:00-41:09 E024-016', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-queen-springs-water","aliases":["Queen-Springs-Wasser und Mikroplastikabwägung"],"tags":["Ausleitung","Erfahrungsheilkunde","Folge 024","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Ausleitung"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Keine grossen Wassermengen bei Herz-/Nierenproblemen ohne Beratung. Markenname, Siliziumgehalt und Verpackung verifizieren.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E024-016; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nAls praktische Siliziumquelle nennt Klinghardt ein als Queen Springs verstandenes Flaschenwasser. Regelmaessiges Trinken solle Aluminium ausleiten; eine moegliche Mikroplastikbelastung der Flasche sei gegen den erwarteten Nutzen abzuwägen.\n\n## Genannte Mittel oder Verfahren\n- Siliziumreiches Mineralwasser, wahrscheinlich Queen Springs\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nIm Video werden keine Tagesmenge und keine Dauer genannt.\n\n## Sprecher und Fundstellen\n- Folge 024 · 40:00-41:09 · E024-016 · DK\n\n## Unabhängige Evidenzeinordnung\nS23 ist eine kleine vorlaeufige Studie; mehr Aluminium im Urin ist kein Nachweis dauerhafter Gehirnentgiftung oder Krankheitsbehandlung. Nutzen, Mineralgehalt, Verpackung und Nieren-/Fluessigkeitsstatus sind getrennt zu beurteilen.\n\n## Sicherheit · HOCH\nKeine grossen Wassermengen bei Herz-/Nierenproblemen ohne Beratung. Markenname, Siliziumgehalt und Verpackung verifizieren.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('9f8e5571-b582-58b5-a7c3-c3ab6372cfba', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-edta-dmsa-calendar', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Kalenderprotokoll mit oralem/IV-EDTA, DMSA und Metallbefunden', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-edta-dmsa-calendar', 'unknown', 'Folge 015 32:50-34:19 E015-015', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-edta-dmsa-calendar","aliases":["Kalenderprotokoll mit oralem/IV-EDTA, DMSA und Metallbefunden"],"tags":["Ausleitung","Erfahrungsheilkunde","Folge 015","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DM","Sprecheraussage"],"therapeutic_topics":["Ausleitung"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Diesen Kalender nicht nachmachen. EDTA-Salzformen sind nicht austauschbar; falsches Dinatrium-EDTA kann tödliche Hypokalzämie verursachen. CaNa2EDTA kann Nierenversagen und Zinkverlust auslösen; DMSA kann Neutropenie, Lebertoxizität, schwere Haut-/Überempfindlichkeitsreaktionen und fetale Schäden verursachen [S20-S22]. Nur bei bestätigter Exposition und unter medizinisch-toxikologischer Leitung.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E015-015; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nDamit komplexe Pläne umgesetzt würden, drucke die Praxis einen leeren Kalender und trage jede Einnahme ein. Als Beispiel nennt Musnick ein EDTA-Protokoll mit DMSA zur Entfernung von Quecksilber und Blei. DMSA werde nach dem Auto-Track ''drei Tage aus zwei Wochen'' gegeben. Bei einer oralen Variante stehe EDTA an drei Tagen pro Woche im Kalender; alternativ erwähnt er Infusionen und danach orales EDTA an zwei Tagen pro Woche. Zusätzlich würden die drei DMSA-Tage markiert. Danach hätten Patienten nicht mehr wegen Unklarheit angerufen. Musnick behandle häufig Metalle; Blei und Quecksilber sehe er oft. Aluminium erscheine eher im Haar und wenig im Urin. Long COVID umfasse aus seiner Sicht mindestens sieben Bereiche, werde aber wegen der Belastung erst später integriert.\n\n## Genannte Mittel oder Verfahren\n- Orales EDTA oder Infusions-EDTA; DMSA/Succimer; Kalenderplan; Haar- und Urinmetalltests; späteres Long-COVID-Programm\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nOrales EDTA: 3 Tage/Woche oder nach Infusionen 2 Tage/Woche. DMSA: 3 Tage in einem Zweiwochenzeitraum [Formulierung unsicher]. Einzelmenge, Salzform, Infusionsplan, Überlappung, Dauer und Laborgrenzen fehlen.\n\n## Sprecher und Fundstellen\n- Folge 015 · 32:50-34:19 · E015-015 · DM\n\n## Unabhängige Evidenzeinordnung\nChelation ist eine risikoreiche Therapie für klar dokumentierte Vergiftung, nicht für unspezifische Beschwerden oder bloße Nachweisbarkeit [S19-S22]. Succimer ist laut US-Label für bestimmte pädiatrische Bleivergiftung zugelassen, erfordert CBC-, Leber- und Nierenkontrollen und soll nicht gleichzeitig mit anderen Chelatoren gegeben werden [S21]. Calciumdinatrium-EDTA ist verschreibungspflichtig, schlecht oral resorbiert, für Bleivergiftung injizierbar zugelassen und trägt eine Warnung vor potenziell tödlicher Toxizität [S22]. Post-Chelator-Urinwerte sind nicht validiert [S20]; Haaranalyse hat erhebliche Kontaminations- und Interpretationsgrenzen [S23].\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Diesen Kalender nicht nachmachen. EDTA-Salzformen sind nicht austauschbar; falsches Dinatrium-EDTA kann tödliche Hypokalzämie verursachen. CaNa2EDTA kann Nierenversagen und Zinkverlust auslösen; DMSA kann Neutropenie, Lebertoxizität, schwere Haut-/Überempfindlichkeitsreaktionen und fetale Schäden verursachen [S20-S22]. Nur bei bestätigter Exposition und unter medizinisch-toxikologischer Leitung.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('378571b4-8326-52ee-a6c5-544c427a8526', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-cistus-lyme', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Cistus als Resilienz-, Biofilm- und Lyme-Mittel', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-cistus-lyme', 'unknown', 'Folge 007 06:36-11:55 E007-003', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-cistus-lyme","aliases":["Cistus als Resilienz-, Biofilm- und Lyme-Mittel"],"tags":["Erfahrungsheilkunde","Folge 007","Interne Prüfung","Klinghardt-Talks","Pflanzenheilkunde","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Michele Milligan (Einzelzuordnung nicht strukturell kodiert)","Sprecheraussage"],"therapeutic_topics":["Pflanzenheilkunde"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Keine Gallonen-Dosis uebernehmen. Bei Kindern Diagnostik, Fluessigkeits-/Elektrolytrisiko, Produktreinheit und wirksame Behandlung priorisieren.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E007-003; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nCistus staerke Resilienz, straffe eine Proteinschicht und helfe bei Biofilmen. Ein seit zwei Jahren schwer krankes Kind mit angeblich sicher diagnostizierter Lyme-Erkrankung sei durch taeglich bis ueber eine Gallone Cistus-Tee gesund geworden und spaeter Surfmeister geworden.\n\n## Genannte Mittel oder Verfahren\n- Cistus incanus/creticus als Tee oder Extrakt; Produkt im Video nicht immer eindeutig.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nIm Video nur als Anekdote: täglich bis über eine Gallone Cistus-Tee. Keine reproduzierbare Patientendosis.\n\n## Sprecher und Fundstellen\n- Folge 007 · 06:36-11:55 · E007-003 · Dr. Dietrich Klinghardt; Michele Milligan (Einzelzuordnung nicht strukturell kodiert)\n\n## Unabhängige Evidenzeinordnung\nCistus-Laborstudien betreffen aetherisches Oel, lipophile oder ethanolische Extrakte. In der Studie PMID 20432627 hemmte der waessrige Extrakt das Borrelienwachstum nicht. Keine kontrollierte Humanstudie belegt Tee gegen Lyme oder Biofilm.\n\n## Sicherheit · BEACHTEN\nKeine Gallonen-Dosis uebernehmen. Bei Kindern Diagnostik, Fluessigkeits-/Elektrolytrisiko, Produktreinheit und wirksame Behandlung priorisieren.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('f1a8421b-5575-5b5c-bd41-2776c0b3cea8', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-hyaluronic-acid-timing', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Hyaluronsaeure als angebliche Borrelien-Lockung', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-hyaluronic-acid-timing', 'unknown', 'Folge 007 11:56-14:26 E007-004', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-hyaluronic-acid-timing","aliases":["Hyaluronsaeure als angebliche Borrelien-Lockung"],"tags":["Erfahrungsheilkunde","Folge 007","Interne Prüfung","Klinghardt-Talks","Pathogene und Infektionen","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Michele Milligan (Einzelzuordnung nicht strukturell kodiert)","Sprecheraussage"],"therapeutic_topics":["Pathogene und Infektionen"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Datenbankstatus unsupported_mechanism. Nicht als Dosierungsreihenfolge oder diagnostischen Nachweis automatisieren.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E007-004; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nBorrelien wuerden Bandscheiben, Baender und Gelenke wegen Hyaluronsaeure bevorzugen. Ein Tropfen Hyaluronsaeure habe in einer nicht beschriebenen Gewebeprobe innerhalb von Sekunden hunderttausende Spirochaeten sichtbar gemacht. Sublinguale Hyaluronsaeure solle 30 Minuten vor antimikrobiellen Mitteln gegeben werden.\n\n## Genannte Mittel oder Verfahren\n- BioPure Hyaluronic Acid, Dunkelfeldmikroskopie und anschliessender CockTail.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nSublinguale Hyaluronsäure 30 Minuten vor den antimikrobiellen Mitteln; Tropfenzahl und Konzentration werden im Video nicht genannt.\n\n## Sprecher und Fundstellen\n- Folge 007 · 11:56-14:26 · E007-004 · Dr. Dietrich Klinghardt; Michele Milligan (Einzelzuordnung nicht strukturell kodiert)\n\n## Unabhängige Evidenzeinordnung\nKeine Borrelien-, Human-, Pharmakokinetik- oder Replikationsstudie fuer dieses Lockmodell gefunden. Ein nicht dokumentiertes Mikroskopbild kann Artefakte, Kontamination und Organismenidentitaet nicht klaeren.\n\n## Sicherheit · BEACHTEN\nDatenbankstatus unsupported_mechanism. Nicht als Dosierungsreihenfolge oder diagnostischen Nachweis automatisieren.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('c56f9ae0-687f-5b49-a74c-882260fc5542', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-lymphatic-detox-bartonella', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Bartonella, Implantate und Lymphatic Detox', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-lymphatic-detox-bartonella', 'unknown', 'Folge 007 20:13-22:44 E007-008', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-lymphatic-detox-bartonella","aliases":["Bartonella, Implantate und Lymphatic Detox"],"tags":["Erfahrungsheilkunde","Folge 007","Interne Prüfung","Klinghardt-Talks","Pflanzenheilkunde","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Michele Milligan (Einzelzuordnung nicht strukturell kodiert)","Sprecheraussage"],"therapeutic_topics":["Pflanzenheilkunde"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Mechanische Komplikation, typische Implantatinfektion, Thrombose und neurologische Red Flags zuerst abklaeren. Keine ART-/Symptomdiagnose oder Kraeutertherapie als Ersatz.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E007-008; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nNach Knie-/Hueftimplantat oder mehreren Bandscheibenoperationen laute die Diagnose meist Bartonella plus Lyme. Lymphatic Detox sei ein verdeckt benanntes, besonders erfolgreiches Naturmittel fuer Bartonella und Bestandteil der Mischung.\n\n## Genannte Mittel oder Verfahren\n- BioPure Lymphatic Detox; ART oder symptombasierte Zuordnung.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nIm Video beispielhaft 2 Teile Lymphatic Detox in einer personalisierten Mischung; absolute Menge und Häufigkeit fehlen.\n\n## Sprecher und Fundstellen\n- Folge 007 · 20:13-22:44 · E007-008 · Dr. Dietrich Klinghardt; Michele Milligan (Einzelzuordnung nicht strukturell kodiert)\n\n## Unabhängige Evidenzeinordnung\nBartonella- oder Lyme-Infektionen von Implantaten sind seltene Fallberichte, nicht die uebliche Erklaerung postoperativer Beschwerden. Keine Humanstudie belegt dieses Produkt. Bartonella-Serologie kann kreuzreagieren/persistieren; PCR-Sensitivitaet ist begrenzt.\n\n## Sicherheit · BEACHTEN\nMechanische Komplikation, typische Implantatinfektion, Thrombose und neurologische Red Flags zuerst abklaeren. Keine ART-/Symptomdiagnose oder Kraeutertherapie als Ersatz.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('897073ad-de3e-5dea-bcdb-d9683d513843', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-core-sequence', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Borrelien, Mangan und Core-S-zu-Core-Sequenz', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-core-sequence', 'unknown', 'Folge 007 44:39-47:27 E007-018', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-core-sequence","aliases":["Borrelien, Mangan und Core-S-zu-Core-Sequenz"],"tags":["Erfahrungsheilkunde","Folge 007","Interne Prüfung","Klinghardt-Talks","Pflanzenheilkunde","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Michele Milligan (Einzelzuordnung nicht strukturell kodiert)","Sprecheraussage"],"therapeutic_topics":["Pflanzenheilkunde"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Hoher Dosiswarnstatus: Etikettmaxima liefern B6 bis 107/114 mg und Zink 57/60 mg pro Tag; Core bis 10,8 mg Mangan vor Nahrung. Core-S liefert bis 6.000 mcg und Core bis 12.000 mcg Biotin/Tag. Risiken: B6-Neuropathie, Zink-bedingter Kupfermangel/Anaemie/Neutropenie, Antibiotikainteraktionen und biotinbedingte Laborfehlresultate.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E007-018; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nBorrelien seien die einzigen Bakterien ohne Eisenbedarf und koennten mit Mangan leichter ueberleben. Deshalb solle jeder mit angenommener Lyme-Erkrankung zwei bis drei Monate Core-S ohne Mangan nehmen und dann zu Core wechseln, auch ohne Diagnose.\n\n## Genannte Mittel oder Verfahren\n- Core-S gefolgt von Core.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nIm Video: Core-S für 2-3 Monate, danach Wechsel zu Core. Kapselzahl und Einnahmehäufigkeit werden im Video nicht genannt.\n\n## Sprecher und Fundstellen\n- Folge 007 · 44:39-47:27 · E007-018 · Dr. Dietrich Klinghardt; Michele Milligan (Einzelzuordnung nicht strukturell kodiert)\n\n## Unabhängige Evidenzeinordnung\nBorrelia burgdorferi ist ungewoehnlich eisenunabhaengig und benoetigt Mangantransporter/-enzyme; das ist mechanistisch belegt. Keine Humanstudie zeigt, dass Nahrungsmanganrestriktion oder Core-S/Core die Bakterienlast oder Symptome verbessert.\n\n## Sicherheit · BEACHTEN\nHoher Dosiswarnstatus: Etikettmaxima liefern B6 bis 107/114 mg und Zink 57/60 mg pro Tag; Core bis 10,8 mg Mangan vor Nahrung. Core-S liefert bis 6.000 mcg und Core bis 12.000 mcg Biotin/Tag. Risiken: B6-Neuropathie, Zink-bedingter Kupfermangel/Anaemie/Neutropenie, Antibiotikainteraktionen und biotinbedingte Laborfehlresultate.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('587e32a0-c475-5a00-b738-36b73cc930e0', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-artemisinin-babesia-label-only', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Artemisinin als angebliches Muss bei Babesiose', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-artemisinin-babesia-label-only', 'unknown', 'Folge 007 18:36-20:12; 38:40-40:07 E007-007', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-artemisinin-babesia-label-only","aliases":["Artemisinin als angebliches Muss bei Babesiose"],"tags":["Erfahrungsheilkunde","Folge 007","Interne Prüfung","Klinghardt-Talks","Pflanzenheilkunde","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Michele Milligan (Einzelzuordnung nicht strukturell kodiert)","Sprecheraussage"],"therapeutic_topics":["Pflanzenheilkunde"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Symptomatische Babesiose kann schwere Haemolyse und Organversagen verursachen. Artemisinin nicht als Muss oder Ersatz erfassen; Blutbild, Parasitaemie und leitliniengerechte Versorgung sichern.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E007-007; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nArtemisinin sei die Hauptbehandlung fuer Babesien und ein absolutes Muss. Artemisinin-Pulver werde mit einer Artemisia-Ganzpflanzentinktur kombiniert; eine iranische Studie soll die Ganzpflanze als gleich wirksam und billiger fuer Malaria gezeigt haben.\n\n## Genannte Mittel oder Verfahren\n- BioPure Artemisinin und Artemis/Artemisia annua.\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nKeine klare Videomenge. Im Quellenfeld dokumentierte Produktetiketten sind keine Sprecherdosis.\n\n## Sprecher und Fundstellen\n- Folge 007 · 18:36-20:12; 38:40-40:07 · E007-007 · Dr. Dietrich Klinghardt; Michele Milligan (Einzelzuordnung nicht strukturell kodiert)\n\n## Unabhängige Evidenzeinordnung\nArtemisinin zeigte Aktivitaet gegen B. duncani in vitro; Mausdaten zu B. microti stuetzen Artemisinin/Artemisia allein nicht. CDC/IDSA empfehlen Atovaquon plus Azithromycin, alternativ Clindamycin plus Chinin. WHO unterstuetzt nichtpharmazeutische Artemisia-Formen nicht fuer Malaria.\n\n## Sicherheit · HOCH\nSymptomatische Babesiose kann schwere Haemolyse und Organversagen verursachen. Artemisinin nicht als Muss oder Ersatz erfassen; Blutbild, Parasitaemie und leitliniengerechte Versorgung sichern.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('5dcd16a1-555e-538b-8a08-ad3b3c215472', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-iv-antibiotics-six-months', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Familiäre Lyme-Erkrankungen und sechsmonatige intravenöse Doppelantibiose des Sohnes', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-iv-antibiotics-six-months', 'unknown', 'Folge 019 14:12-16:32 E019-006', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-iv-antibiotics-six-months","aliases":["Familiäre Lyme-Erkrankungen und sechsmonatige intravenöse Doppelantibiose des Sohnes"],"tags":["Erfahrungsheilkunde","Folge 019","Interne Prüfung","Klinghardt-Talks","Pathogene und Infektionen","Quellenkarte","Sprecher: BW","Sprecheraussage"],"therapeutic_topics":["Pathogene und Infektionen"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Keine monatelange IV-Kombinationsantibiose oder Behandlung Angehöriger ohne gesicherte Indikation, Erregerbezug, Dosis-, Labor-, Katheter- und Interaktionskontrolle. Sepsis, Thrombose, Anaphylaxie, Organtoxizität, C. difficile und Resistenz sind möglich [S07, S08, S37].","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E019-006; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nWeitkus erklärt ihre intensive Beschäftigung mit Lyme-Borreliose durch viele Zecken auf einem Inselgrundstück. Sie selbst, ihr Mann, ihre Söhne und ein Enkel seien erkrankt. Deutsche leitliniengerechte Behandlung habe aus ihrer Sicht nicht geholfen. Als ein Klinikchef Literaturhinweise zur Behandlung ihres Sohnes abgelehnt und sie beleidigt habe, habe sie den Sohn nach Hause geholt und ein halbes Jahr lang täglich morgens und abends mit zwei verschiedenen intravenösen Antibiotika behandelt. Er gehe heute gut; von Heilung wolle sie wegen verbleibender Persistenzformen dennoch nicht sprechen.\n\n## Genannte Mittel oder Verfahren\n- Langzeitige intravenöse Kombination aus zwei nicht benannten Antibiotika\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nTäglich morgens und abends über sechs Monate; Wirkstoffe und Einzeldosen fehlen.\n\n## Sprecher und Fundstellen\n- Folge 019 · 14:12-16:32 · E019-006 · BW\n\n## Unabhängige Evidenzeinordnung\nFür frühe Neuroborreliose reichen laut S3-Leitlinie 14 Tage, für späte 14-21 Tage; orale Doxycyclin- und Beta-Laktamtherapie zeigen vergleichbare Wirksamkeit, valide Daten für Kombinationen fehlen [S04]. Verlängerte Antibiotika helfen bei PTLDS im Mittel nicht besser als Placebo und erhöhen Nebenwirkungen [S07, S08].\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Keine monatelange IV-Kombinationsantibiose oder Behandlung Angehöriger ohne gesicherte Indikation, Erregerbezug, Dosis-, Labor-, Katheter- und Interaktionskontrolle. Sepsis, Thrombose, Anaphylaxie, Organtoxizität, C. difficile und Resistenz sind möglich [S07, S08, S37].\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('627e1cdd-62ce-5e27-bcf6-862a4040a753', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-four-antibiotics-cycles', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Vierfachantibiotika, Gewebekompartimente und Fünf-Wochen-Zyklen', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-four-antibiotics-cycles', 'unknown', 'Folge 019 51:57-55:22 E019-022', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-four-antibiotics-cycles","aliases":["Vierfachantibiotika, Gewebekompartimente und Fünf-Wochen-Zyklen"],"tags":["Erfahrungsheilkunde","Folge 019","Interne Prüfung","Klinghardt-Talks","Pathogene und Infektionen","Quellenkarte","Sprecher: DK; BW","Sprecheraussage"],"therapeutic_topics":["Pathogene und Infektionen"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Vierfach- und IV-Langzeitregime nicht übernehmen und onkologische Behandlung nicht ersetzen. Erreger, Organmanifestation, Resistenz, QT-Zeit, Leber/Niere, Blutbild, Interaktionen und Katheterrisiken benötigen fachärztliche Kontrolle [S07, S08, S37].","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E019-022; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt leitet zur Therapie über und behauptet, Charles Ray Jones habe Kindern mit Lernstörungen, Autismus und sogar Krebserkrankungen durch hochdosierte intravenöse Antibiotika geholfen; IV-Antibiotika seien achtmal wirksamer als orale. Weitkus beschreibt pathogenbezogene Kombinationen: zwei verschiedene Antibiotika morgens und zwei abends, darunter intrazellulär, im Blut und über die Blut-Hirn-Schranke wirkende Mittel. Wegen eines behaupteten 28-Tage-Generationszyklus habe sie nach 35 Tagen beziehungsweise fünf Wochen gewechselt und oft sechs bis neun Monate behandelt. Für Babesien nennt sie die Malariamittel Malarone, wahrscheinlich Wellvone und Riamet.\n\n## Genannte Mittel oder Verfahren\n- Pathogenspezifische vierfache, teils intravenöse Antibiotikakombination in Fünf-Wochen-Zyklen; mehrere Antimalariamittel bei Babesiose\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nZwei Antibiotika morgens plus zwei abends; Wechsel nach 35 Tagen/5 Wochen; insgesamt oft 6-9 Monate; keine mg-Dosen.\n\n## Sprecher und Fundstellen\n- Folge 019 · 51:57-55:22 · E019-022 · DK; BW\n\n## Unabhängige Evidenzeinordnung\nDie S3-Leitlinie findet keine validen Daten für Antibiotikakombinationen und empfiehlt bei Neuroborreliose 14 beziehungsweise 14-21 Tage; Doxycyclin und Beta-Laktame sind neurologisch ähnlich wirksam [S04]. Eine pauschale achtfache IV-Wirkung oder Krebsbehandlung ist nicht belegt. Bei bestätigter Babesiose sind Atovaquon plus Azithromycin oder Clindamycin plus Chinin etablierte Kombinationen, meist 7-10 Tage bei immunkompetenten Erkrankten [S26]. Die genannten Antimalariamittel sind nicht beliebig austauschbar.\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Vierfach- und IV-Langzeitregime nicht übernehmen und onkologische Behandlung nicht ersetzen. Erreger, Organmanifestation, Resistenz, QT-Zeit, Leber/Niere, Blutbild, Interaktionen und Katheterrisiken benötigen fachärztliche Kontrolle [S07, S08, S37].\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('af0192ac-cde5-5d73-b206-9ab3e0bfcb3d', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-antiparasitics-seizures', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Anfälle durch Lyme/Parasiten und 20 Tage hoch dosierte Antiparasitika', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-antiparasitics-seizures', 'unknown', 'Folge 022 1:07:18-1:08:38 E022-031', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-antiparasitics-seizures","aliases":["Anfälle durch Lyme/Parasiten und 20 Tage hoch dosierte Antiparasitika"],"tags":["Erfahrungsheilkunde","Folge 022","Interne Prüfung","Klinghardt-Talks","Pathogene und Infektionen","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Pathogene und Infektionen"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Keine 20-tägige Hochdosis bei Kindern aufgrund ART. Status epilepticus ist ein Notfall; Albendazol kann Leber/Knochenmark schädigen und intrakranielle Entzündung provozieren.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E022-031; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt bejaht Lyme als Anfallsursache. Bei Lymepatienten mit Anfällen finde ART jedoch häufig wandernde Parasitenlarven im Gehirn, wahrscheinlich Ascaris oder andere Würmer. Er beginne dann oft antiparasitär, mit einem im Track als ''oxide'' verzerrten Mittel oder Albendazol, 20 Tage in ziemlich hoher Dosis; dies habe bei vielen Anfallsleiden, besonders Kindern, Wunder bewirkt. Nach Unfall oder Kopfverletzung würde er anders vorgehen.\n\n## Genannte Mittel oder Verfahren\n- ART-Parasitendiagnose; wahrscheinlich Nitazoxanid/Alinia [unsicher] oder Albendazol\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\n20 Tage, ''ziemlich hohe Dosen''; Wirkstoff- und mg-Dosis unvollständig.\n\n## Sprecher und Fundstellen\n- Folge 022 · 1:07:18-1:08:38 · E022-031 · DK\n\n## Unabhängige Evidenzeinordnung\nAnfälle haben zahlreiche Ursachen und erfordern Anamnese, EEG, Bildgebung und gezielte Laborprüfung [S31]. Bei echter Neurozystizerkose hängen Antiparasitika von Zahl, Ort und Stadium ab; Anfallskontrolle und Steroide können zentral sein, und Abtötung kann Entzündung akut verschlimmern [S30].\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Keine 20-tägige Hochdosis bei Kindern aufgrund ART. Status epilepticus ist ein Notfall; Albendazol kann Leber/Knochenmark schädigen und intrakranielle Entzündung provozieren.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('22ff8efb-2139-530f-afbc-9228b46ab817', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-series-kits-fsm-brain-diet', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Falltherapie mit Bindern, Kräutern, DesBio-Series-Kits, FSM und Gehirndiät', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-series-kits-fsm-brain-diet', 'unknown', 'Folge 015 28:54-32:50 E015-014', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-series-kits-fsm-brain-diet","aliases":["Falltherapie mit Bindern, Kräutern, DesBio-Series-Kits, FSM und Gehirndiät"],"tags":["Erfahrungsheilkunde","Folge 015","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DM; DK stellt eine Zwischenfrage","Sprecheraussage","Therapieverfahren"],"therapeutic_topics":["Therapieverfahren"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. SAFETY_HOLD: Keine aktive Lyme-/Bartonella- oder Schimmelerkrankung mit Series Kits, Bindern oder Kräutern selbst behandeln. Medikamente und Kräuter können interagieren; Binder können Arzneien/Nährstoffe binden. Lebensmittelallergien und Ernährungsausgewogenheit beachten.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E015-014; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nMusnick begann im Fall mit Bindern, Bitterstoffen und spezialisierten Bindern gegen die festgestellten Schimmel-Biotoxine, wartete aber nicht monatelang bis zur Lyme-Behandlung. Für Lyme und Koinfektionen seien Kräuter unbedingt nötig, gelegentlich Medikamente. Er nutzte Kräuter nach nicht benannten Protokollen und statt LDI Homöopathie von DesBio: ''Series Kits'' für Lyme oder Bartonella wechselten alle drei Tage die Potenz, würden aufgebaut und anschließend umgekehrt. Nach vielen guten Ergebnissen über Jahre behandelte er damit Lyme und wahrscheinlich Bartonella und ergänzte FSM für das Gehirn. Nach etwa drei Monaten habe der Patient nur noch wenige Prozent Einschränkung berichtet. Musnick entwarf außerdem eine ''brain diet'' mit viel Petersilie wegen Apigenin, Petersilienpesto und -smoothies sowie viel Cholin aus Eiern von käfigfrei gehaltenen Hühnern. Apigenin mache Mikroglia weniger entzündlich und steigere Wachstumsfaktoren. Der Mann sei wieder Vater, leistungsfähig bei der Arbeit und sportlich aktiv gewesen. Musnick wertet dies als Erfolg der Integration aus Kräutern und Homöopathie; bei Gehirnproblemen gebe es immer mehrere Ursachen.\n\n## Genannte Mittel oder Verfahren\n- Schimmelbinder/Bitterstoffe; Lyme-Kräuter, gelegentlich Medikamente; DesBio-Series-Kits; FSM; Petersilie/Apigenin; Eier/Cholin\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nSeries-Kit-Wechsel alle 3 Tage mit Aufbau und Umkehr; Verlauf etwa 3 Monate. Keine Produkt-, Kräuter-, Binder-, Petersilien-, Eier- oder Medikamentendosis.\n\n## Sprecher und Fundstellen\n- Folge 015 · 28:54-32:50 · E015-014 · DM; DK stellt eine Zwischenfrage\n\n## Unabhängige Evidenzeinordnung\nNCCIH findet wenig Evidenz für Homöopathie bei spezifischen Erkrankungen [S14]; DesBio weist selbst darauf hin, dass Produktclaims nicht von der FDA bewertet sind und die Mittel nicht zur Diagnose, Behandlung oder Heilung bestimmt sind [S26]. Leitlinienbasierte Lyme-Behandlung verwendet definierte Antibiotika je Manifestation; Kräuter, Series Kits und FSM sind dafür nicht etabliert [S03]. Petersilie und Eier sind Lebensmittel, aber präklinische Apigeninmechanismen belegen keine Behandlung von Mikroglia, Lyme oder kognitivem Abbau. Der Fall kann den Anteil jeder Maßnahme nicht trennen.\n\n## Sicherheit · HOCH\nSAFETY_HOLD: Keine aktive Lyme-/Bartonella- oder Schimmelerkrankung mit Series Kits, Bindern oder Kräutern selbst behandeln. Medikamente und Kräuter können interagieren; Binder können Arzneien/Nährstoffe binden. Lebensmittelallergien und Ernährungsausgewogenheit beachten.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('dc719bf7-f2e9-536e-8ac4-647f6147e609', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-topical-melatonin', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Metallische Abschirmung, geerdete Farben und hoch dosierte Melatonincreme', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-topical-melatonin', 'unknown', 'Folge 014 1:01:21-1:03:42 E014-023', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-topical-melatonin","aliases":["Metallische Abschirmung, geerdete Farben und hoch dosierte Melatonincreme"],"tags":["Erfahrungsheilkunde","Folge 014","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage","Therapieverfahren"],"therapeutic_topics":["Therapieverfahren"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. SAFETY_HOLD: 50-500 mg Melatonin nicht selbst anwenden; das liegt weit über üblichen Schlafdosen. Sedierung, Stürze, Fahrtüchtigkeit, Blutverdünner, Epilepsie, Schwangerschaft, Kinder und Produktqualität ärztlich prüfen [S03]. Propolis kann schwere Allergien auslösen. Erdung nur fachgerecht [S41].","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E014-023; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt verweist auf Baubiologie und behauptet, ein Haus lasse sich mit metallischen Farben abschirmen. Er nennt Swiss Shield, metallische Vorhänge und komplett gestrichene Decken, Böden und Wände seines Behandlungsraums; Farben und Vorhänge seien geerdet, wodurch er sich dort sehr gut fühle. Nachts verwende man Melatonin-Hautcreme. Auf der Folie stünden 80 bis 500 mg; gesprochen wird wahrscheinlich eine bevorzugte Dosis von 50 mg, wobei das Auto-Track-Wort davor unklar ist. In Deutschland seien nur kleine Mengen von etwa 3 oder 5 mg aus dem dm-Markt zugänglich. Höhere Dosen seien fantastisch gegen Krebs und neurologische Erkrankungen. Propolis liefere 80 Prozent der Heilwirkung von Melatonin und wirke zusätzlich gegen Retroviren, Krebs und alle neurologischen Erkrankungen.\n\n## Genannte Mittel oder Verfahren\n- Metallische Abschirmfarbe/-vorhänge; Swiss Shield; Erdung; Melatonincreme; Propolis\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nFolie: 80-500 mg Melatonin. Gesprochen wahrscheinlich 50 mg. Vergleich: 3 oder 5 mg. Anwendungsfläche, Konzentration, Zeitpunkt und Dauer fehlen; Dosiswiderspruch bleibt offen.\n\n## Sprecher und Fundstellen\n- Folge 014 · 1:01:21-1:03:42 · E014-023 · DK\n\n## Unabhängige Evidenzeinordnung\nMelatonin reguliert circadiane Rhythmen; für hohe Dosen und Langzeitsicherheit bestehen erhebliche Lücken [S03]. EMA-Produkte verwenden indikationsbezogen niedrige retardierte Dosen [S38, S39]. Der Cochrane-Review zu Krebs fand überwiegend sehr unsichere Evidenz und stützt keine pauschale Krebstherapie mit 50-500 mg topisch [S37]. Für ''80 Prozent'' Ersatzwirkung von Propolis sowie Heilung aller neurologischen Erkrankungen fehlt ein klinischer Nachweis. Abschirmwirkung ist frequenz-, material- und installationsabhängig.\n\n## Sicherheit · HOCH\nSAFETY_HOLD: 50-500 mg Melatonin nicht selbst anwenden; das liegt weit über üblichen Schlafdosen. Sedierung, Stürze, Fahrtüchtigkeit, Blutverdünner, Epilepsie, Schwangerschaft, Kinder und Produktqualität ärztlich prüfen [S03]. Propolis kann schwere Allergien auslösen. Erdung nur fachgerecht [S41].\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('ea6e43a9-077f-57ff-ac5f-5b9c274c7cfd', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-high-dose-iod-pneumonia', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Iod verdränge Fluorid nicht; Hochdosis-Iod bei Pneumonie und Produktverfügbarkeit', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-high-dose-iod-pneumonia', 'unknown', 'Folge 022 15:55-17:48 E022-008', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-high-dose-iod-pneumonia","aliases":["Iod verdränge Fluorid nicht; Hochdosis-Iod bei Pneumonie und Produktverfügbarkeit"],"tags":["Erfahrungsheilkunde","Folge 022","Interne Prüfung","Klinghardt-Talks","Pathogene und Infektionen","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Pathogene und Infektionen"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Keine Hochdosis aus Prozentangaben ableiten. Atemnot, Zyanose, Verwirrtheit oder niedrige Sauerstoffsättigung sind akut abklärungsbedürftig; Schilddrüse, Schwangerschaft und Medikamente berücksichtigen.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E022-008; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt widerspricht der Vorstellung, Iod könne Fluorid wegen gemeinsamer Halogengruppe aus Gewebe verdrängen, und illustriert dies mit einer Maus-Katze-Analogie unterschiedlicher Molekülgrößen. Viele Menschen seien iodarm, doch Iod habe einen engen Dosisbereich und publizierte Überdosierungstodesfälle. Trotzdem gebe er bei Pneumonie oder akuter Infektion zehn Tage bis zwei Wochen hohe Dosen und reduziere anschließend auf eine moderate Lugol-Dosis. Er beklagt schlechtere Verfügbarkeit, nennt früher 20 Prozent in England, dann fünf beziehungsweise zwei Prozent in den USA und J. Crow''s als verwendetes Produkt.\n\n## Genannte Mittel oder Verfahren\n- Hoch dosiertes Iod bei Pneumonie/akuter Infektion; anschließende Lugol-Erhaltungsdosis\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nHohe Dosis 10 Tage bis 2 Wochen; Konzentrationen 20%, 5% und 2% im Verfügbarkeitskontext, keine Tropfen- oder Iodmenge.\n\n## Sprecher und Fundstellen\n- Folge 022 · 15:55-17:48 · E022-008 · DK\n\n## Unabhängige Evidenzeinordnung\nIod ist essenziell, kann in Übermaß aber Schilddrüsenstörungen und Vergiftung verursachen [S09]. Das Video belegt weder Fluoridentgiftung noch Wirksamkeit hoch dosierten Iods gegen Pneumonie; bakterielle/virale Pneumonie erfordert ursachen- und schweregradbezogene Versorgung.\n\n## Sicherheit · HOCH\nKeine Hochdosis aus Prozentangaben ableiten. Atemnot, Zyanose, Verwirrtheit oder niedrige Sauerstoffsättigung sind akut abklärungsbedürftig; Schilddrüse, Schwangerschaft und Medikamente berücksichtigen.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('57fb2a2e-6db4-57aa-ae9b-d5c12715bed9', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-lactoferrin-novalytic-insuless', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Lactoferrin + Novalytic + InsuLess', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-lactoferrin-novalytic-insuless', 'unknown', 'Folge 010 1:02:21-1:03:48; 1:22:54-1:24:55 E010-007', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-lactoferrin-novalytic-insuless","aliases":["Lactoferrin + Novalytic + InsuLess"],"tags":["Erfahrungsheilkunde","Folge 010","Interne Prüfung","Klinghardt-Talks","Medikamente und Nährstoffe","Quellenkarte","Sprecher: Dr. Dietrich Klinghardt; Maria Crisler","Sprecheraussage"],"therapeutic_topics":["Medikamente und Nährstoffe"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Proprietäre Inhaltsstoffe, kumulative Dosen, Milchprotein und Interaktionen prüfen; keine universelle Kombination.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E010-007; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nSynergie für Eisen, rote Blutkörperchen, Hydrogele und Nieren\n\n## Genannte Mittel oder Verfahren\n- Lactoferrin + Novalytic + InsuLess\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nMorgens gemeinsam; Novalytic später erneut; Lactoferrin 300 mg. Mengen von Novalytic und InsuLess fehlen in diesem Kombinationsblock.\n\n## Sprecher und Fundstellen\n- Folge 010 · 1:02:21-1:03:48; 1:22:54-1:24:55 · E010-007 · Dr. Dietrich Klinghardt; Maria Crisler\n\n## Unabhängige Evidenzeinordnung\nKeine unabhängige Kombinationsstudie; Mikroskop-/Urinbilder sind keine validierten klinischen Endpunkte.\n\n## Sicherheit · BEACHTEN\nProprietäre Inhaltsstoffe, kumulative Dosen, Milchprotein und Interaktionen prüfen; keine universelle Kombination.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('e1c28b0c-dc0c-5655-adae-d76a34d36464', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-blue-room-light-autism', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Blaue Raumlampe beruhige autistische Kinder in fuenf bis sechs Minuten', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-blue-room-light-autism', 'unknown', 'Folge 023 54:00-55:21 E023-025', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-blue-room-light-autism","aliases":["Blaue Raumlampe beruhige autistische Kinder in fuenf bis sechs Minuten"],"tags":["Erfahrungsheilkunde","Erkrankungen und Symptome","Folge 023","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Erkrankungen und Symptome"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Kinder nicht zur Blaulichtexposition zwingen. Sensorische Praeferenzen, Migräne, Epilepsie, Schlafrhythmus und Kommunikation beachten; Autismusunterstuetzung nicht ersetzen.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E023-025; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt wiederholt, Haut und zirkulierende Lymphozyten seien spezifisch lichtempfindlich. Eine blaue Lampe im Zimmer mache autistische Kinder innerhalb von fuenf bis sechs Minuten sofort ruhig. Derselbe Effekt trete auf, wenn die Kinder mit dem Ruecken zum Licht saessen; erklaert werde er durch Lichtrezeptoren von Lymphozyten und Hautzellen, die farbabhaengige Signale ans Zentralnervensystem sendeten.\n\n## Genannte Mittel oder Verfahren\n- Blaue Raumbeleuchtung bei autistischen Kindern\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nBehaupteter Wirkungseintritt nach 5-6 Minuten; Wellenlaenge, Luxzahl, Dauer, Raumgroesse und Endpunkt fehlen.\n\n## Sprecher und Fundstellen\n- Folge 023 · 54:00-55:21 · E023-025 · DK\n\n## Unabhängige Evidenzeinordnung\nAutistische Menschen koennen Licht sehr unterschiedlich als beruhigend, aktivierend oder sensorisch belastend erleben. NICE empfiehlt individuelle sensorische Anpassungen, keine standardisierte Blaulichtbehandlung [S11]. Extraokulaere circadiane Wirkung ist nicht automatisch gegeben [S24].\n\n## Sicherheit · BEACHTEN\nKinder nicht zur Blaulichtexposition zwingen. Sensorische Praeferenzen, Migräne, Epilepsie, Schlafrhythmus und Kommunikation beachten; Autismusunterstuetzung nicht ersetzen.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('971c55c4-aedd-514b-8cd1-b7c2c3d2a078', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-melatonin-route-ear-point', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Melatoninroute, Hatha-Yoga, PhotonWave und Ohrakupunktur', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-melatonin-route-ear-point', 'unknown', 'Folge 016 1:01:43-1:03:58 E016-024', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-melatonin-route-ear-point","aliases":["Melatoninroute, Hatha-Yoga, PhotonWave und Ohrakupunktur"],"tags":["Erfahrungsheilkunde","Folge 016","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage","Therapieverfahren"],"therapeutic_topics":["Therapieverfahren"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Keine Hochdosiscreme oder Zäpfchen aus dieser Routenbehauptung ableiten. Ohr nicht mit Nadeln, Laser oder vibrierenden Geräten selbst behandeln; Verbrennung, Infektion, Trommelfell-/Hautverletzung und Fehlanwendung vermeiden.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E016-024; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nOral würden nach mehr als 5 mg Melatonin kaum noch Wirkstoff absorbiert und nur sehr wenig erreiche das Gehirn; als Hautcreme oder rektales Zäpfchen komme dagegen viel im Gehirn an. Natürlich könnten bestimmte Hatha-Yoga-Techniken die Melatoninkonzentration erhöhen und die Epiphyse heilen. PhotonWave habe anhand von Patientenurin fantastische Verbesserungen der Melatoninproduktion gezeigt. Klinghardt verweist außerdem auf Frank Bahrs Ohrakupunktur, Nogier und ein Buch von wahrscheinlich Beate Strittmatter. Ein Epiphysen-Ohrpunkt könne mit Laser, Nadel, Klopfen, Massage oder heute bevorzugt einer elektrischen Zahnbürste stimuliert werden. Eine persönliche chronische Erkrankung sei durch einen Ohrpunkt geheilt worden; der Krankheitsbegriff ist im Track unverständlich.\n\n## Genannte Mittel oder Verfahren\n- Melatonincreme/-zäpfchen; Hatha-Yoga; PhotonWave; Ohrakupunktur mit Laser, Nadel, Klopfen, Massage oder Zahnbürste\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nBehauptete orale Absorptionsgrenze >5 mg; sonst keine Dosis. Ohrpunkt ohne Dauer/Frequenz.\n\n## Sprecher und Fundstellen\n- Folge 016 · 1:01:43-1:03:58 · E016-024 · DK\n\n## Unabhängige Evidenzeinordnung\nMelatonin ist kein Peptid, und die pauschale 5-mg-Absorptionsgrenze beziehungsweise bevorzugte Gehirnaufnahme durch Creme/Zäpfchen wird durch die angegebenen Quellen nicht gestützt [S03, S07]. Akupunkturevidenz ist indikationsspezifisch; daraus folgt keine validierte Epiphysenheilung oder Melatoninsteigerung [S33]. Urinmetabolite beweisen keine lokale Gehirnkonzentration.\n\n## Sicherheit · BEACHTEN\nKeine Hochdosiscreme oder Zäpfchen aus dieser Routenbehauptung ableiten. Ohr nicht mit Nadeln, Laser oder vibrierenden Geräten selbst behandeln; Verbrennung, Infektion, Trommelfell-/Hautverletzung und Fehlanwendung vermeiden.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('b2249666-f102-5f08-8385-d4b943fea8d4', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-borax-pineal', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Borax im Kaffee, unlesbare Messerspitzendosis und Boronfunktionen', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-borax-pineal', 'unknown', 'Folge 022 07:34-09:58 E022-004', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-borax-pineal","aliases":["Borax im Kaffee, unlesbare Messerspitzendosis und Boronfunktionen"],"tags":["Erfahrungsheilkunde","Folge 022","Interne Prüfung","Klinghardt-Talks","Medikamente und Nährstoffe","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Medikamente und Nährstoffe"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. EXTREMER SAFETY_HOLD: Die unklare Messerspitzendosis nicht nachmachen. Borax kann toxisch sein; Produktidentität, elementare Boronmenge, Nierenfunktion und Gesamtzufuhr wären zwingend.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E022-004; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nAuf Kevins Frage nach Borax gegen Epiphysenverkalkung sagt Klinghardt, er nehme morgens Borax im Kaffee. Die Messerspitzendosis zerfällt im Auto-Track zu ''502,000 milligrams'' und ist deshalb nicht belastbar. Boron reguliere Hormone, Knochen und Zähne und sei Bestandteil vieler Enzyme. Er verbindet Nebenschilddrüsenprobleme häufig mit Lyme, beschreibt meist einen gutartigen Tumor einer von vier Drüsen und warnt ab US-Kalziumwerten von ungefähr 10,5 bis 10,7.\n\n## Genannte Mittel oder Verfahren\n- Orale Einnahme von Borax im Kaffee\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nEine Messerspitze; Zahlenangabe ASR-unauflösbar (''502,000 mg'') und ausdrücklich nicht ausführbar.\n\n## Sprecher und Fundstellen\n- Folge 022 · 07:34-09:58 · E022-004 · DK\n\n## Unabhängige Evidenzeinordnung\nBoron ist ein Spurenelement, Borax jedoch ein chemisches Salz und keine frei dosierbare Lebensmittelzutat [S04]. Primärer Hyperparathyreoidismus wird mit Kalzium und PTH diagnostiziert; häufig liegt ein Adenom vor [S05]. Eine generelle Lyme-Ursache wird dadurch nicht belegt.\n\n## Sicherheit · EXTREM\nEXTREMER SAFETY_HOLD: Die unklare Messerspitzendosis nicht nachmachen. Borax kann toxisch sein; Produktidentität, elementare Boronmenge, Nierenfunktion und Gesamtzufuhr wären zwingend.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge'),
      ('e389d49d-71d3-5904-931d-7cdf517c5259', 'd41998ea-5f70-519b-88db-b87513747c1d', 'source:klinghardt-talks-001-025-borax-calcium', 'imported_unreviewed', 'reference_work', 'Klinghardt-Quellenkarte: Herzstillstandsanekdote, Kalzium und behauptete Boraxwirkung', 'Klinghardt Talks 001-025', NULL, '', 'klinghardt-talks-001-025-borax-calcium', 'unknown', 'Folge 022 09:58-11:38 E022-005', convert_from(decode('', 'base64'), 'UTF8'), 100, 'Die Karte ist quellengeprueft; ihre Sprecherempfehlung, Videodosis, Evidenz- und Sicherheitsabschnitte bleiben getrennt und unveroeffentlicht.', '{"admin_only":true,"patient_facing_allowed":false,"review_status":"unreviewed","card_type":"klinghardt_talks_source_card","candidate_id":"klinghardt-talks-001-025-borax-calcium","aliases":["Herzstillstandsanekdote, Kalzium und behauptete Boraxwirkung"],"tags":["Erfahrungsheilkunde","Erkrankungen und Symptome","Folge 022","Interne Prüfung","Klinghardt-Talks","Quellenkarte","Sprecher: DK","Sprecheraussage"],"therapeutic_topics":["Erkrankungen und Symptome"],"dosage_status":"unverified","evidence_level":"unrated","safety_notes":"Interne attribuierte Quellenkarte; keine Empfehlung, keine Selbstanwendung und keine Patientenfreigabe. Bei Verwirrtheit, Schwäche, Rhythmusstörung oder schwerer Hyperkalzämie akut medizinisch handeln. Borax nicht als Heimtest oder Ersatz für Endokrinologie verwenden.","source_citations":[{"label":"Klinghardt-Gesamtsammlung 001-025: E022-005; DOCX SHA-256 FB2631F0EFFDE4A05D74A0C1B114340F0E91839F24A04416F8A53A5006E6B2F7"},{"label":"Klinghardt-Praxisnavigator 001-025; PDF SHA-256 20DCE7162CC99A44B12D988F2ADBB12DC471A5FD67AECF66786BC4196E71C26B"}],"source_file":"external/klinghardt-talks/001-025/praxisnavigator","content":"**Status:** Attribuierte interne Quellenkarte aus den Klinghardt-Talks. Sie dokumentiert die Sprecheraussage, ist keine Praxisempfehlung, nicht fachlich freigegeben und nicht patientengerichtet.\n\n## Sprecherbehauptung\nKlinghardt erzählt von einem jungen Mann mit Herzstillstand in einer Notaufnahme in Roswell, den er reanimiert habe; der Kalziumwert habe bei über 11 gelegen. Daraus leitet er ab, Borax könne bei erhöhtem Parathormon in 60 bis 70 Prozent der Fälle den Kalziumwert senken. Bleibe der Effekt aus, solle man per Ultraschall die vergrößerte Drüse finden und durch eine kleine Operation entfernen. Einen eigenen ART-Test von Borax gegen die Epiphyse habe er jedoch noch nicht durchgeführt und nennt die Anwendung nur wahrscheinlich eine gute Idee.\n\n## Genannte Mittel oder Verfahren\n- Borax als behauptete Kalziumsenkung; Ultraschall und Parathyreoidektomie\n\n## Dosis, Häufigkeit und Dauer laut Video\n**Videodosisstatus:** Unvollständig oder unsicher; fehlende Angaben wurden nicht extern ergänzt.\n\nBehauptete Erfolgsrate 60-70 Prozent; keine kontrollierte Dosis oder Dauer.\n\n## Sprecher und Fundstellen\n- Folge 022 · 09:58-11:38 · E022-005 · DK\n\n## Unabhängige Evidenzeinordnung\nHyperkalzämie kann gefährlich sein; Diagnose erfordert wiederholte Laborwerte, PTH, Nieren-/Knochenprüfung und Ursachenabklärung [S05]. NIDDK beschreibt Monitoring, Cinacalcet und indikationsgerechte Operation, nicht Borax als Standardtherapie.\n\n## Sicherheit · BEACHTEN\nBei Verwirrtheit, Schwäche, Rhythmusstörung oder schwerer Hyperkalzämie akut medizinisch handeln. Borax nicht als Heimtest oder Ersatz für Endokrinologie verwenden.\n\n## Redaktionshinweis\nOriginalaussage, Attribution, Evidenzeinordnung und Sicherheitswarnung bleiben getrennte Ebenen. Fehlende oder widersprüchliche Evidenz löscht die naturheilkundliche Aussage nicht; sie verhindert bis zur manuellen Prüfung deren Freigabe."}'::jsonb, 'general_knowledge');
