      ('5d773dee-2b7c-56b1-b7a4-755e32b239fe', 'ffe44e71-68ab-55dd-8f3f-1ef92b227417', 'source:internal-nutrient-review:uk-sacn-fsa-independent-source-access-audit-2026-08-08', 'imported_unreviewed', 'practice_document', 'uk-sacn-fsa-independent-source-access-audit-2026-08-08: Record accessible current or official UK source routes that can supplement the general NHS frames without importing product, condition or dose decisions.', 'Interne Quellen- und Sicherheitspruefung', NULL, '', '', 'unknown', 'docs/uk-sacn-fsa-independent-source-access-audit-2026-08-08.json', '{"schema_version":1,"audited_at":"2026-08-08T21:30:00.000Z","latest_access_check":{"checked_at":"2026-08-09T00:00:00.000Z","method":"GET_with_followed_redirects","source_urls_checked":12,"http_200_responses":12,"access_errors":0,"interpretation":"Access confirmation only; it does not change source scope, recency class, citation restrictions or gate status."},"search_gaps":[{"query_scope":"GOV.UK search for SACN vitamin K","result":"No direct current SACN vitamin-K report identified; returned results were general SACN collection or other nutrient material.","use_status":"not_imported"},{"query_scope":"GOV.UK search for SACN magnesium","result":"No direct current SACN magnesium report identified; returned results were general SACN collection or unrelated nutrition material.","use_status":"not_imported"},{"query_scope":"GOV.UK search for SACN zinc","result":"No direct current SACN zinc report identified; the results included the general SACN collection and an older 2008 zinc-related record, neither imported as a current nutrient-specific frame.","use_status":"not_imported"},{"query_scope":"GOV.UK search for COT folic acid tolerable upper level","result":"No separate direct COT folic-acid upper-level report identified; two guessed official publication routes returned 404 and the search returned the current DHSC folic-acid guidance plus an older consultation response.","use_status":"not_imported"},{"query_scop