      ('9079f564-a779-5248-9530-5ca3c8780909', 'ffe44e71-68ab-55dd-8f3f-1ef92b227417', 'safety:strunz-20260804-eisen-caps:form-and-population', 'imported_unreviewed', '5c0a4403-3943-5b43-a6c8-7ee9513da9f2', 'precaution', 'require_review', 'The declaration lists iron bisglycinate and iron sulfate component amounts alongside an iron nutrient amount. NHS and SACN provide general population context, but independent form-specific equivalence and reconciliation of declared component and nutrient amounts is not established. The manufacturer warning topics are triage inputs only. NHS and SACN provide general population context, not product or patient clearance; population-specific assessment remains open and must be separate from form and interaction review.', '807b5110-84c8-5314-8912-21892f43f375', 'docs/strunz-iron-form-population-preflight-2026-08-08.json', '{"schema_version":1,"reviewed_at":"2026-08-08T21:00:00.000Z","publication":"unpublished_internal_preflight","product_source_id":"strunz-20260804-eisen-caps","product_source":"docs/strunz-public-product-fact-candidates-2026-08-04.json","review_gate":"form_and_population","status":"open_not_cleared_blocked_read_only","declared_product_facts":{"product":"Eisen Caps","serving":"1 capsule","iron":"14 mg","vitamin_c":"84 mg","declared_component_amounts":[{"name":"iron bisglycinate","amount":"43.5 mg"},{"name":"iron sulfate","amount":"13.5 mg"},{"name":"acerola fruit juice powder","amount":"498 mg"}],"manufacturer_warning_topics":["medical consultation for men, postmenopausal women, and pregnancy","avoid additional iron supplements"]},"independent_sources_checked":[{"source_url":"https://www.nhs.uk/conditions/vitamins-and-minerals/iron/","status":"accessible_general_reference","form_specific_equivalence":"not_established","population_specific_product_clearance":"not_established","page_last_reviewed":"2020-08-03"},{"source_url":"https://www.gov.uk/government/publications/sacn-iron-and-health-report","status":"accessible_inde